using Library.Crosscutting.Security;
using Library.Data;
using Library.Data.Sql;
using Library.Model.Enums;
using Library.Service.Enums;
using Library.Service.Helpers;
using Library.Service.Logs;
using OTSBD;
using Syncfusion.XlsIO;
using System;
using System.Collections.Generic;
using System.Data;
using System.Drawing;
using System.IO;
using System.Reflection;
using Library.Service.Currencies;
using System.Threading;
using System.Linq;
using Library.Core;

namespace Library.Accounting.Accounts
{
    public class AccountsStatusDashboardService
    {
        private readonly ISqlRepository _sqlRepository;
        private readonly ICompanyParallelCurrencyService _companyParallelCurrencyService;

        public AccountsStatusDashboardService(ISqlRepository sqlRepository
            , ICompanyParallelCurrencyService companyParallelCurrencyService

            )
        {
            _sqlRepository = sqlRepository;
            _companyParallelCurrencyService = companyParallelCurrencyService;
        }

        #region Vendor Tab
        public List<Dictionary<string, object>> GetPartyPaymentStatusSummaryData(string companyGroupId, string companyId, string plantId, string fromDate, string toDate)
        {
            var searchDate = "";
            var searchDateODue = "";
            if (fromDate != "" && toDate != "")
            {

                searchDate = "AND ( convert(Date,IV.PostingDate) Between '" + fromDate + @"' and '" + toDate + @"')";
                searchDateODue = "AND ( convert(Date,I.PostingDate) Between '" + fromDate + @"' and '" + toDate + @"')";
            }
            if (fromDate == "" && toDate != "")
            {

                searchDate = "AND ( convert(Date,IV.PostingDate) <= '" + toDate + @"' )";
                searchDateODue = "AND ( convert(Date,I.PostingDate) <= '" + toDate + @"' )";
            }

            var sql = @"SELECT NoOfInvoice,	isSelected,	PartyNature,	PartyGroup,	PartyCategory,	PartySubCategory,	ResponsiblePerson,	PartyId	,PartyName	,CurrencyCode,	Advance,	DebitNote,	CreditNote,
                    Gross,	SetOff,	Balance,(ActualBalance-Advance-DebitNote)ActualBalance,(Balance-Advance-DebitNote)NetBalance,	LedgerBalanceAmount,	WriteOffPendingPost	,BooksGross,	BooksSetOff,	BooksBalance,	OverDueMoreThan30,	OverDueMoreThan15,
                    OverDueLessThan15,	TodayBalance,	OneToSevenBalance,	EightToThirtyBalance,	ThirtyToSixtyBalance,	Onword60,	BooksDiscountAmount,	TaxAmount	,IsCustomer
                     FROM 
                    (SELECT count(X.NoOfInvoice) NoOfInvoice,convert(bit,0) AS isSelected,x.PartyNature,x.PartyGroup,x.PartyCategory,x.PartySubCategory,x.ResponsiblePerson,X.PartyId,X.PartyName,x.CurrencyCode
                    ,ISNULL((SELECT sum(VDCA.DrAmount)+sum(ISNULL(ADDW.AdditionalAdvanceAmount,0)) -sum(ISNULL(AW.AdvanceWriteOffBooksAmount,0)) FROM TRN.Advance A
					INNER JOIN  [TRN].[AdvanceDetail] AD ON AD.AdvanceId=A.Id
					INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdvanceDetailId=AD.Id
				    INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCA ON VDCA.VoucherDetailId=VDA.Id
                    LEFT JOIN (select SUM(VDCW.CrAmount)AdvanceWriteOffBooksAmount,AdvanceId from [TRN].[AdvanceWriteOffDetail] AWD
					    INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.AdvanceWriteOffDetailId=AWD.Id
					    INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
                        LEFT JOIN [TRN].[AdvanceWriteOff] AW ON AW.Id=AWD.AdvanceWriteOffId 
				        LEFT JOIN [TRN].[Voucher] VW ON VW.Id=AW.VoucherId 
				        WHERE VW.IsPark=0 AND VW.Archive=0
                        AND convert(Date,AW.PostingDate) <= '" + toDate + @"' GROUP BY AdvanceId)AW ON AW.AdvanceId=A.Id
                    LEFT JOIN (select SUM(VDCW.DrAmount)AdditionalAdvanceAmount,AdvanceId from [TRN].[AdvanceWriteOffDetail] AWD
				        INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.AdvanceWriteOffDetailId=AWD.Id
				        INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
                        LEFT JOIN [TRN].[AdvanceWriteOff] AW ON AW.Id=AWD.AdvanceWriteOffId 
				        LEFT JOIN [TRN].[Voucher] VW ON VW.Id=AW.VoucherId 
				        WHERE VW.IsPark=0 AND VW.Archive=0
                        and ( convert(Date,AW.PostingDate) <= '" + toDate + @"' and AWD.IsAdditionalAdvance=1)
                        GROUP BY AdvanceId)ADDW ON ADDW.AdvanceId=A.Id
					where A.PlantId='" + plantId + @"' and A.PartyId=X.PartyId and A.PartyType='Vendor'  and A.SourceType='VendorAdvance' AND A.IsPark=0 AND convert(Date,A.PostingDate) <= '" + toDate + @"'  group by A.PartyId ),0) Advance 
					 , ISNULL((SELECT SUM(VDC.DrAmount) - SUM(ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0))  FROM [TRN].[AdjustmentNote] A
					 INNER JOIN  [TRN].[AdjustmentNoteDetail] AD ON AD.AdjustmentNoteId=A.Id
                     INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdjustmentNoteDetailId=AD.Id
                     INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VDA.Id
					 LEFT JOIN (select CASE WHEN SUM(ISNULL(VDCW.CrAmount,0))>0 THEN SUM(ISNULL(VDCW.CrAmount,0))
		                                    ELSE SUM(ISNULL(VDCW.DrAmount,0)) END AdjustmentNoteWriteOffBooksAmount,AdjustmentNoteId from [TRN].[InvoiceWriteOffDetail] IWD
										INNER JOIN [TRN].[InvoiceWriteOff] IW ON IW.Id=IWD.InvoiceWriteOffId
										INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.InvoiceWriteOffDetailId=IWD.Id
										 INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
										where IW.IsPark=0 AND IWD.AdjustmentNoteId is not null AND convert(Date,IW.PostingDate) <= '" + toDate + @"'
										GROUP BY  IWD.AdjustmentNoteId)W ON W.AdjustmentNoteId=AD.AdjustmentNoteId
					where A.PlantId='" + plantId + @"' and A.PartyId=X.PartyId and VDA.PartyType='Vendor' and A.SourceType in('DebitNote','InventoryReturnPayable')  AND A.IsPark=0 AND convert(Date,A.PostingDate) <= '" + toDate + @"'  group by A.PartyId ),0) DebitNote 
                , ISNULL((SELECT SUM(VDC.CrAmount) - SUM(ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0))  FROM [TRN].[AdjustmentNote] A
					 INNER JOIN  [TRN].[AdjustmentNoteDetail] AD ON AD.AdjustmentNoteId=A.Id
                     INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdjustmentNoteDetailId=AD.Id
                     INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VDA.Id
					 LEFT JOIN (select SUM(ISNULL(VDCW.DrAmount,0))AdjustmentNoteWriteOffBooksAmount,AdjustmentNoteId from [TRN].[InvoiceWriteOffDetail] IWD
										INNER JOIN [TRN].[InvoiceWriteOff] IW ON IW.Id=IWD.InvoiceWriteOffId
										INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.InvoiceWriteOffDetailId=IWD.Id
										 INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
										where IW.IsPark=0 AND IWD.AdjustmentNoteId is not null AND convert(Date,IW.PostingDate) <= '" + toDate + @"'
										GROUP BY  IWD.AdjustmentNoteId)W ON W.AdjustmentNoteId=AD.AdjustmentNoteId
					where A.PlantId='" + plantId + @"' and A.PartyId=X.PartyId and VDA.PartyType='Vendor' and A.SourceType='CreditNote'  AND A.IsPark=0 AND convert(Date,A.PostingDate) <= '" + toDate + @"'  group by A.PartyId ),0) CreditNote
				, SUM(X.Gross) Gross 
				,SUM(X.SetOff) SetOff
				,SUM(X.Balance) Balance
                ,SUM(X.ActualBalance) ActualBalance
                ,ISNULL((SELECT  round(SUM(ISNULL(CC.CompanyCurrencyCrAmount, 0)) - SUM(ISNULL(CC.CompanyCurrencyDrAmount, 0)),2) AS LedgerBalanceAmount
                    FROM [TRN].[VoucherDetail] AS VD
                    LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                    LEFT JOIN (SELECT VDC.VoucherDetailId, VDC.DrAmount AS CompanyCurrencyDrAmount, VDC.CrAmount AS CompanyCurrencyCrAmount
	                    FROM [TRN].[VoucherDetailCurrency] AS VDC
	                    JOIN [SCS].[CompanyParallelCurrency] AS CPC ON CPC.CurrencyId=VDC.ParallelCurrencyId
	                    WHERE CPC.ParallelCurrencyType='CompanyCurrency' 
                    ) AS CC ON CC.VoucherDetailId=VD.Id
                    WHERE V.Archive=0 AND V.IsPark=0 AND V.PlantId='" + plantId + @"' AND convert(Date,V.PostingDate) <= '" + toDate + @"' AND VD.PartyId=X.PartyId AND VD.PartyType IN ('Vendor') 
					GROUP BY VD.PartyId),0) LedgerBalanceAmount
                ,CASE WHEN (SELECT COUNT(V.Id)NoOfPendingPostWriteOff
                    FROM [TRN].[VoucherDetail] AS VD
		            LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
		            WHERE  V.IsPark=1  AND VD.PartyType='Vendor'  AND V.PlantId='" + plantId + @"' AND VD.PartyId=X.PartyId
		            AND V.SourceType in ('CreditNoteSetOff','CustomerAdvanceWriteOff','CustomerBanksReceipt','CustomerReceipt','DebitNoteSetOff','ReceiptByBank','VendorAdvanceWriteOff','VendorPayment')
		            AND  convert(Date,V.PostingDate) <= '" + toDate + @"' 
		            GROUP BY VD.PartyId)>0 THEN 'Yes' ELSE '' END WriteOffPendingPost
                ,SUM(X.BooksGross) BooksGross
				,SUM(X.BooksSetOff) BooksSetOff
				,SUM(X.BooksBalance) BooksBalance
				,sum(X.ODueMoreThan30) OverDueMoreThan30
				,sum(X.ODueMoreThan15) OverDueMoreThan15
                ,sum(X.ODueLessThan15) OverDueLessThan15
                ,sum(X.TodayBalance) TodayBalance
                ,sum(X.OneToSevenBalance) OneToSevenBalance
			   ,sum(X.EightToThirtyBalance) EightToThirtyBalance
				,sum(X.ThirtyToSixtyBalance) ThirtyToSixtyBalance
				,sum(X.Onword60) Onword60
                ,sum(x.BooksDiscountAmount)BooksDiscountAmount
                ,SUM(x.TaxAmount)TaxAmount
                ,CASE WHEN (SELECT COUNT(Id) FROM HKP.CompanyParty WHERE PartyId=X.PartyId AND PartyType='Customer')>0 THEN 'Yes' ELSE 'No' END IsCustomer
                FROM (
                SELECT IV.PartyId NoOfInvoice,P.PartyNature,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,IV.PartyId,P.Code PartyCode,P.UserName PartyName,c.Code CurrencyCode
                 , ISNULL(IVD.InvoiceBooksAmount,0) AS Gross
				, ISNULL(IVD.SetOffBooksAmount ,0) AS SetOff
				, ISNULL(IVD.InvoiceBooksAmount-IVD.SetOffBooksAmount,0) AS Balance
                , ISNULL(IVD.InvoiceBooksAmount,0) AS BooksGross
				, ISNULL(IVD.SetOffBooksAmount,0) AS BooksSetOff
				, ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0) AS BooksBalance
				, ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IV.WrittenOffAmount*IV.CompanyCurrencyRate,0) AS ActualBalance
                , ISNULL(OM30.ODueMoreThan30*IV.CompanyCurrencyRate ,0) ODueMoreThan30
                , ISNULL(OM15.ODueMoreThan15*IV.CompanyCurrencyRate,0) ODueMoreThan15
                , ISNULL(OV.OverDdueBalance*IV.CompanyCurrencyRate,0) ODueLessThan15
				, ISNULL(TB.TodayBalance*IV.CompanyCurrencyRate,0) TodayBalance
				, ISNULL(OTS.OneToSevenBalance*IV.CompanyCurrencyRate,0) OneToSevenBalance
				, ISNULL(ETT.EightToThirtyBalance*IV.CompanyCurrencyRate,0) EightToThirtyBalance
				, ISNULL(TTS.ThirtyToSixtyBalance*IV.CompanyCurrencyRate,0) ThirtyToSixtyBalance
				, ISNULL(O60.Onword60*IV.CompanyCurrencyRate,0) Onword60
				, ISNULL(IVD.InvoiceBooksAmount,0) AS GrossTranAmount
				, ISNULL(IVD.InvoiceBooksAmount*IV.CompanyCurrencyRate,0) AS BooksGrossAmount
                ,isnull( DIWD.DiscountAmount*IV.CompanyCurrencyRate,0)as BooksDiscountAmount
                ,isnull( IWD.TaxAmount*IV.CompanyCurrencyRate,0)as TaxAmount
                FROM [TRN].[Invoice] AS IV 
                 JOIN (select IDE.InvoiceId,VD.PartyId
				 ,SUM(VDC.CrAmount) + SUM(ISNULL(AID.AdditionalAmount,0))  InvoiceBooksAmount ,SUM(ISNULL(IwV.SetOffBooksAmount,0)) SetOffBooksAmount
						FROM  [TRN].[InvoiceDetail] IDE
                        LEFT JOIN (SELECT SUM(ISNULL(Amount,0)) AdditionalAmount,InvoiceDetailId FROM trn.AdditionalInvoiceDetail   GROUP BY InvoiceDetailId) AS AID ON AID.InvoiceDetailId=IDE.Id
						LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IDE.Id
						LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
						LEFT JOIN [TRN].[Voucher] AS VI ON VI.Id=VD.VoucherId
						LEFT JOIN (SELECT iwd.InvoiceDetailId,VD.PartyId
						,SUM(VDC.DrAmount) SetOffBooksAmount
							FROM  [TRN].[InvoiceWriteOffDetail] iwd 
							JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
							LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
							LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
							 JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
							WHERE WV.IsPark=0 AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' )
							GROUP BY iwd.InvoiceDetailId,VD.PartyId
							)AS IwV ON IwV.InvoiceDetailId=IDE.Id AND VD.PartyId=IwV.PartyId
						WHERE VI.IsPark=0 and VD.PartyType='Vendor' --AND VD.PartyId='202017395'
						GROUP BY IDE.InvoiceId,VD.PartyId
				 ) AS IVD ON IVD.InvoiceId=IV.Id AND IVD.PartyId=IV.PartyId
                    LEFT JOIN (SELECT wd.InvoiceId,sum(wd.Amount) TaxAmount FROM TRN.InvoiceWriteOffDetail wd
                        LEFT JOIN TRN.InvoiceWriteOff w on wd.InvoiceWriteOffId =w.id
                        where w.PaymentSource='Tax'
                        group by wd.InvoiceId
                        ) IWD ON IWD.InvoiceId=IV.Id
                LEFT JOIN (SELECT wd.InvoiceId,sum(wd.Amount) DiscountAmount FROM TRN.InvoiceWriteOffDetail wd
                        LEFT JOIN TRN.InvoiceWriteOff w on wd.InvoiceWriteOffId =w.id
                        where w.PaymentSource='Discount'
                        group by wd.InvoiceId
                        ) DIWD ON DIWD.InvoiceId=IV.Id
                LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                LEFT JOIN [TRN].[Voucher] AS V ON V.Id=IV.VoucherId
                LEFT JOIN [SCS].[Currency] AS C ON C.Id=IV.CurrencyId
                LEFT JOIN [ORG].[Entity] AS EN ON EN.Id=IV.EntityId
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ODueMoreThan30 FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<-30 
							and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OM30 ON OM30.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ODueMoreThan15 FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>=-30
							and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OM15 ON OM15.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS OverDdueBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>=-15
							and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OV ON OV.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS TodayBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)=0 and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) TB ON TB.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS OneToSevenBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<=7 
							and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OTS ON OTS.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS EightToThirtyBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<=30 
							and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) ETT ON ETT.Id=IV.Id

								LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ThirtyToSixtyBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<=60
							and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) TTS ON TTS.Id=IV.Id



				 LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS Onword60 FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>60 and 
							I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) O60 ON O60.Id=IV.Id
                
                WHERE IV.Archive=0  AND V.IsPark=0 AND IV.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable')
               AND IV.CompanyGroupId='" + companyGroupId + "'   AND IV.CompanyId='" + companyId + "' AND IV.PlantId='" + plantId + @"' " + searchDate + @"
                AND ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0)>0 
                UNION ALL
                SELECT  IV.PartyId NoOfInvoice,P.PartyNature,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,IV.PartyId,P.Code PartyCode,P.UserName PartyName,c.Code CurrencyCode
				, ISNULL(IVD.InvoiceBooksAmount,0) AS Gross,
                  ISNULL(IVD.SetOffBooksAmount ,0) AS SetOff
				 , ISNULL(IVD.InvoiceBooksAmount-IVD.SetOffBooksAmount,0) AS Balance

                , ISNULL(IVD.InvoiceBooksAmount,0) AS BooksGross
				, ISNULL(IVD.SetOffBooksAmount,0) AS BooksSetOff
				, ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0) AS BooksBalance
				, ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.ActualWrittenOffAmount*IV.CompanyCurrencyRate,0) AS ActualBalance
                , ISNULL(OM30.ODueMoreThan30*IV.CompanyCurrencyRate,0) ODueMoreThan30
                , ISNULL(OM15.ODueMoreThan15*IV.CompanyCurrencyRate,0) ODueMoreThan15
                , ISNULL(OV.OverDdueBalance*IV.CompanyCurrencyRate,0) ODueLessThan15
				, ISNULL(TB.TodayBalance*IV.CompanyCurrencyRate,0) TodayBalance
				, ISNULL(OTS.OneToSevenBalance*IV.CompanyCurrencyRate,0) OneToSevenBalance
				, ISNULL(ETT.EightToThirtyBalance*IV.CompanyCurrencyRate,0) EightToThirtyBalance
				, ISNULL(TTS.ThirtyToSixtyBalance*IV.CompanyCurrencyRate,0) ThirtyToSixtyBalance
				, ISNULL(O60.Onword60*IV.CompanyCurrencyRate,0) Onword60
				, ISNULL(IVD.InvoiceBooksAmount,0) AS GrossTranAmount
				, ISNULL(IVD.InvoiceBooksAmount*IV.CompanyCurrencyRate,0) AS BooksGrossAmount
                ,isnull( DIWD.DiscountAmount*IV.CompanyCurrencyRate,0)as BooksDiscountAmount
                ,isnull( IWD.TaxAmount*IV.CompanyCurrencyRate,0)as TaxAmount
                FROM [TRN].[Invoice] AS IV 
                 JOIN (select IDE.InvoiceId,VD.PartyId,SUM(VDC.CrAmount) + SUM(ISNULL(AID.AdditionalAmount,0)) InvoiceBooksAmount ,SUM(ISNULL(IwV.SetOffBooksAmount,0)) SetOffBooksAmount
                ,SUM(isnull(IDE.WrittenOffAmount,0))ActualWrittenOffAmount
						FROM  [TRN].[InvoiceDetail] IDE
                        LEFT JOIN (SELECT SUM(ISNULL(Amount,0)) AdditionalAmount,InvoiceDetailId FROM trn.AdditionalInvoiceDetail   GROUP BY InvoiceDetailId) AS AID ON AID.InvoiceDetailId=IDE.Id
						LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IDE.Id
						LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
						LEFT JOIN [TRN].[Voucher] AS VI ON VI.Id=VD.VoucherId
						LEFT JOIN (SELECT iwd.InvoiceDetailId,iw.PartyId
                        ,SUM(VDC.DrAmount) SetOffBooksAmount
							FROM  [TRN].[InvoiceWriteOffDetail] iwd 
							JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
							LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
							LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
							 JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
							WHERE WV.IsPark=0 AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' )
							GROUP BY iwd.InvoiceDetailId,iw.PartyId
							)AS IwV ON IwV.InvoiceDetailId=IDE.Id AND VD.PartyId=IwV.PartyId
						WHERE VI.IsPark=0 --AND VD.PartyId='202017395'
						GROUP BY IDE.InvoiceId,VD.PartyId
				 ) AS IVD ON IVD.InvoiceId=IV.Id AND IVD.PartyId=IV.PartyId
               LEFT JOIN (SELECT wd.InvoiceId,sum(wd.Amount) TaxAmount FROM TRN.InvoiceWriteOffDetail wd
                        LEFT JOIN TRN.InvoiceWriteOff w on wd.InvoiceWriteOffId =w.id
                        where w.PaymentSource='Tax'
                        group by wd.InvoiceId
                        ) IWD ON IWD.InvoiceId=IV.Id
                LEFT JOIN (SELECT wd.InvoiceId,sum(wd.Amount) DiscountAmount FROM TRN.InvoiceWriteOffDetail wd
                        LEFT JOIN TRN.InvoiceWriteOff w on wd.InvoiceWriteOffId =w.id
                        where w.PaymentSource='Discount'
                        group by wd.InvoiceId
                        ) DIWD ON DIWD.InvoiceId=IV.Id
                LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                LEFT JOIN [TRN].[Voucher] AS V ON V.Id=IV.VoucherId
                LEFT JOIN [SCS].[Currency] AS C ON C.Id=IV.CurrencyId
                LEFT JOIN [ORG].[Entity] AS EN ON EN.Id=IV.EntityId
                LEFT JOIN TRN.InventoryReceive IR ON IR.Id=IV.InventoryReceiveId
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ODueMoreThan30 FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<-30 AND I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OM30 ON OM30.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ODueMoreThan15 FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>=-30 AND I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OM15 ON OM15.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS OverDdueBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>=-15 AND I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OV ON OV.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS TodayBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)=0 AND I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) TB ON TB.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS OneToSevenBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<=7 AND I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OTS ON OTS.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS EightToThirtyBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<=30 AND I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) ETT ON ETT.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ThirtyToSixtyBalance FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<=60
							and I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) TTS ON TTS.Id=IV.Id

				 LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS Onword60 FROM TRN.Invoice I 
							WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>60 AND I.SourceType in ('InventoryPayable','ServicePayable') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) O60 ON O60.Id=IV.Id
                
                WHERE IV.Archive=0  AND V.IsPark=0  AND IV.SourceType in ('InventoryPayable','ServicePayable')
                 AND IV.CompanyGroupId='" + companyGroupId + "'   AND IV.CompanyId='" + companyId + "' AND IV.PlantId='" + plantId + @"'
                AND IR.PurchaseDocumentAcceptanceId IS NULL " + searchDate + @"
                 and ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0)>0 

                union all
				 SELECT IV.PartyId NoOfInvoice,P.PartyNature,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,IV.PartyId,P.Code PartyCode,P.UserName PartyName,c.Code CurrencyCode
                 ,ISNULL(IVD.Amount,0) AS Gross
				, ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0)  AS SetOff
				, ISNULL(IVD.Amount*CC.CompanyCurrencyRate,0)-ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0)  AS Balance
                , ISNULL(IVD.Amount*CC.CompanyCurrencyRate,0) AS BooksGross
				,ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0) AS BooksSetOff
				, ISNULL(IVD.Amount*CC.CompanyCurrencyRate,0)-ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0) AS BooksBalance
				, ISNULL(IVD.Amount*CC.CompanyCurrencyRate,0)-ISNULL(IVD.WrittenOffAmount*CC.CompanyCurrencyRate,0) AS ActualBalance
                , ISNULL(OM30.ODueMoreThan30*CC.CompanyCurrencyRate,0) ODueMoreThan30
                , ISNULL(OM15.ODueMoreThan15*CC.CompanyCurrencyRate,0) ODueMoreThan15
                , ISNULL(OV.OverDdueBalance*CC.CompanyCurrencyRate,0) ODueLessThan15
				, ISNULL(TB.TodayBalance*CC.CompanyCurrencyRate,0) TodayBalance
				, ISNULL(OTS.OneToSevenBalance*CC.CompanyCurrencyRate,0) OneToSevenBalance
				, ISNULL(ETT.EightToThirtyBalance*CC.CompanyCurrencyRate,0) EightToThirtyBalance
				, ISNULL(TTS.ThirtyToSixtyBalance*CC.CompanyCurrencyRate,0) ThirtyToSixtyBalance
				, ISNULL(O60.Onword60*CC.CompanyCurrencyRate,0) Onword60
				, ISNULL(IVD.Amount,0) AS GrossTranAmount
				, ISNULL(IVD.Amount*CC.CompanyCurrencyRate,0) AS BooksGrossAmount,0 as BooksDiscountAmount,0 TaxAmount
                FROM [TRN].[AdjustmentNoteDetail] AS IVD
                LEFT JOIN [TRN].[AdjustmentNote] AS IV ON IVD.AdjustmentNoteId=IV.Id
                LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.AdjustmentNoteDetailId=IVD.Id
                LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                LEFT JOIN [SCS].[Currency] AS C ON C.Id=IV.CurrencyId
                LEFT JOIN [ORG].[Entity] AS EN ON EN.Id=IV.EntityId
				 LEFT JOIN (select SUM(ISNULL(VDCW.DrAmount,0))AdjustmentNoteWriteOffBooksAmount,AdjustmentNoteId from [TRN].[InvoiceWriteOffDetail] IWD
										INNER JOIN [TRN].[InvoiceWriteOff] IW ON IW.Id=IWD.InvoiceWriteOffId
										INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.InvoiceWriteOffDetailId=IWD.Id
										 INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
										where IW.IsPark=0 AND IWD.AdjustmentNoteId is not null AND convert(Date,IW.PostingDate) <= '" + toDate + @"'
										GROUP BY  IWD.AdjustmentNoteId)W ON W.AdjustmentNoteId=IVD.AdjustmentNoteId
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ODueMoreThan30 FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)<-30 
							and I.SourceType in ('VendorPayment','CreditNote') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OM30 ON OM30.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ODueMoreThan15 FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)<-15 and DATEDIFF(DAY, GETDATE(),I.PostingDate)>=-30
							and I.SourceType in ('VendorPayment','CreditNote') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0 AND I.IsWrittenOff=0 AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OM15 ON OM15.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS OverDdueBalance FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)<0 and DATEDIFF(DAY, GETDATE(),I.PostingDate)>=-15
							and I.SourceType in ('VendorPayment','CreditNote') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OV ON OV.Id=IV.Id

				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS TodayBalance FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)=0 and I.SourceType in ('VendorPayment','CreditNote') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) TB ON TB.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS OneToSevenBalance FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)>0 and DATEDIFF(DAY, GETDATE(),I.PostingDate)<=7 
							and I.SourceType in ('VendorPayment','CreditNote') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) OTS ON OTS.Id=IV.Id
				LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS EightToThirtyBalance FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)>7 and DATEDIFF(DAY, GETDATE(),I.PostingDate)<=30 
							and I.SourceType in ('VendorPayment','CreditNote') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) ETT ON ETT.Id=IV.Id

								LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS ThirtyToSixtyBalance FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)>30 and DATEDIFF(DAY, GETDATE(),I.PostingDate)<=60
							and I.SourceType in ('VendorPayment','CreditNote') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) TTS ON TTS.Id=IV.Id



				 LEFT JOIN (SELECT Id,SUM(ISNULL(I.Amount - I.WrittenOffAmount,0)) AS Onword60 FROM TRN.AdjustmentNote I 
							WHERE DATEDIFF(DAY, GETDATE(),I.PostingDate)>60 and 
							I.SourceType in ('VendorPayment') 
                            and  I.CompanyGroupId='" + companyGroupId + "'   AND I.CompanyId='" + companyId + "' AND I.PlantId='" + plantId + @"' and I.Archive=0  AND I.IsWrittenOff=0 AND i.IsPark=0 " + searchDateODue + @"
                            group by Id) O60 ON O60.Id=IV.Id
                LEFT JOIN (
                SELECT VDC.ParallelCurrencyId AS CompanyCurrencyId, VDC.FromCurrencyId AS CompanyFromCurrencyId, VDC.ToCurrencyId,
                VDC.ToCurrencyRate AS CompanyCurrencyRate, VDC.ToCurrencyConversion AS CompanyCurrencyConversion, VDC.DrAmount AS CompanyCurrencyAmount, VDC.VoucherDetailId
                FROM [TRN].[VoucherDetailCurrency] AS VDC
                JOIN [SCS].[CompanyParallelCurrency] AS CPC ON CPC.CurrencyId=VDC.ParallelCurrencyId
                WHERE CPC.ParallelCurrencyType='CompanyCurrency' AND CPC.CompanyId='" + companyId + @"'
                ) AS CC ON CC.VoucherDetailId=VD.Id
                
                WHERE IV.Archive=0  AND V.IsPark=0 AND IV.PartyType='Vendor' AND IV.SourceType in ('VendorPayment','CreditNote')
                    AND ISNULL(IVD.Amount*CC.CompanyCurrencyRate,0)-ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0)>0 
               AND IV.CompanyGroupId='" + companyGroupId + "'   AND IV.CompanyId='" + companyId + "' AND IV.PlantId='" + plantId + @"' " + searchDate + @"
                
				)
                X
				--where x.PartyCode='2020100'
                GROUP BY PartyNature,PartyGroup,PartyCategory,PartySubCategory,ResponsiblePerson,PartyId,PartyName,CurrencyCode
                )X1
                order by PartyNature,PartyGroup,PartyName";
            return _sqlRepository.GetDataCollection(sql);

        }

        //Summary Report
        public IWorkbook GetPartyPaymentStatusReport(List<Dictionary<string, object>> MasterLCList, string fromDate, string toDate, string companyGroupId, string companyId, string plantId)
        {
            var excelEngine = new ExcelEngine();
            var report = new ReportUtility();
            var workbook = report.GetWorkbook(ref excelEngine, 3);
            workbook.Version = ExcelVersion.Excel2016;
            IWorksheet worksheet = workbook.Worksheets[0];
            try
            {
                worksheet.Name = "PartyPaymentSummaryReport";

                int COL = 1; int ROW = 6;

                int startCol = COL;
                worksheet[ROW, COL].Text = "Party Nature";
                int colPartyNature = COL;
                worksheet[ROW, COL].ColumnWidth = 12;
                COL++;

                worksheet[ROW, COL].Text = "Party Group";
                int colPartyGroup = COL;
                worksheet[ROW, COL].ColumnWidth = 12;
                COL++;

                worksheet[ROW, COL].Text = "Party Category";
                int colPartyCategory = COL;
                worksheet[ROW, COL].ColumnWidth = 12;
                COL++;

                worksheet[ROW, COL].Text = "Party Sub Category";
                int colPartySubCategory = COL;
                worksheet[ROW, COL].ColumnWidth = 12;
                COL++;

                worksheet[ROW, COL].Text = "Responsible Person";
                int colResponsiblePerson = COL;
                worksheet[ROW, COL].ColumnWidth = 12;
                COL++;

                worksheet[ROW, COL].Text = "Party Id";
                int colPartyCode = COL;
                worksheet[ROW, COL].ColumnWidth = 12;
                COL++;

                worksheet[ROW, COL].Text = "Party";
                int colPartyName = COL;
                worksheet[ROW, COL].ColumnWidth = 35;
                COL++;

                worksheet[ROW, COL].Text = "No Of Invoice";
                int colNoOfInvoice = COL;
                worksheet[ROW, COL].ColumnWidth = 12;
                COL++;

                worksheet[ROW, COL].Text = "Advance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colAdvance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Debit Note";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colDebitNoteAmount = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Credit Note";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colCreditNote = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Books Gross";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colBooksGross = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Books Discount";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colBooksDiscount = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Books Tax";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colTaxAmount = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Books Payment";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colBooksSetOff = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Books Balance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colBooksBalance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Net Balance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colNetBalance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Ledger Balance Amount";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colLedgerBalanceAmount = COL;
                worksheet[ROW, COL].ColumnWidth = 22;
                COL++;

                worksheet[ROW, COL].Text = "Actual Balance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colActualBalance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "WriteOff Pending Post";
                int colWriteOffPendingPost = COL;
                worksheet[ROW, COL].ColumnWidth = 21;
                COL++;

                worksheet[ROW, COL].Text = "Over DueMoreThan30";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colODueMoreThan30 = COL;
                worksheet[ROW, COL].ColumnWidth = 20;
                COL++;

                worksheet[ROW, COL].Text = "Over DueMoreThan15";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colODueMoreThan15 = COL;
                worksheet[ROW, COL].ColumnWidth = 20;
                COL++;

                worksheet[ROW, COL].Text = "Over DueLessThan15";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colODueLessThan15 = COL;
                worksheet[ROW, COL].ColumnWidth = 20;
                COL++;

                worksheet[ROW, COL].Text = "Today Balance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colTodayBalance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "1-7 Balance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colOneToSevenBalance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "8-30 Balance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colEightToThirtyBalance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "30-60 Balance";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colThirtyToSixtyBalance = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Onward 60";
                worksheet[ROW, COL].HorizontalAlignment = ExcelHAlign.HAlignRight;
                int colOnword60 = COL;
                worksheet[ROW, COL].ColumnWidth = 15;
                COL++;

                worksheet[ROW, COL].Text = "Is Customer";
                int colIsCustomer = COL;
                worksheet[ROW, COL].ColumnWidth = 15;

                int endCol = COL;

                worksheet.Range[ROW, startCol, ROW, COL].CellStyle.Font.Size = 12;
                worksheet.Range[ROW, startCol, ROW, COL].CellStyle.Font.Bold = true;

                //worksheet.Range[ROW, startCol, ROW, COL].CellStyle.ColorIndex = ExcelKnownColors.Yellow;
                worksheet.Range[ROW, startCol, ROW, COL].CellStyle.FillBackground = ExcelKnownColors.Grey_40_percent;

                worksheet.Range[ROW, startCol, ROW, COL].BorderAround(ExcelLineStyle.Hair);
                worksheet.Range[ROW, startCol, ROW, COL].BorderInside(ExcelLineStyle.Hair);

                DataTable dt = new DataTable("DD");
                foreach (string item in MasterLCList[0].Keys)
                {
                    //if (item.ToUpper().Contains("ID") || item.ToUpper().Contains("PK") || item.ToUpper().Contains("EJVALUE"))
                    //    continue;

                    dt.Columns.Add(item);
                }


                for (int i = 0; i < MasterLCList.Count; i++)
                {
                    DataRow dr = dt.NewRow();
                    foreach (string item in MasterLCList[i].Keys)
                    {
                        //if (item.ToUpper().Contains("ID") || item.ToUpper().Contains("PK") || item.ToUpper().Contains("EJVALUE"))
                        //    continue;

                        dr[item] = MasterLCList[i][item];
                    }

                    dt.Rows.Add(dr);
                }



                if (dt.Rows.Count == 0)
                {
                    throw new Exception("No Data Found");
                }

                ROW++;
                int StartDataRow = ROW;

                for (int i = 0; i < dt.Rows.Count; i++)
                {
                    //  worksheet[ROW, colSLNO].Number = (i + 1);
                    //worksheet[ROW, colSLNO].Number = i + 1;
                    worksheet[ROW, colNoOfInvoice].Number = clsStaticInfo.dbl(dt.Rows[i]["NoOfInvoice"].ToString());
                    worksheet[ROW, colPartyNature].Text = dt.Rows[i]["PartyNature"].ToString();
                    worksheet[ROW, colPartyGroup].Text = dt.Rows[i]["PartyGroup"].ToString();
                    worksheet[ROW, colPartyCategory].Text = dt.Rows[i]["PartyCategory"].ToString();
                    worksheet[ROW, colPartySubCategory].Text = dt.Rows[i]["PartySubCategory"].ToString();
                    worksheet[ROW, colResponsiblePerson].Text = dt.Rows[i]["ResponsiblePerson"].ToString();
                    worksheet[ROW, colPartyCode].Text = dt.Rows[i]["PartyId"].ToString();
                    worksheet[ROW, colPartyName].Text = dt.Rows[i]["PartyName"].ToString();
                    worksheet[ROW, colAdvance].Number = clsStaticInfo.dbl(dt.Rows[i]["Advance"].ToString());
                    worksheet[ROW, colAdvance].NumberFormat = "#,##0.00;(#,##0.00)";
                    worksheet[ROW, colDebitNoteAmount].Number = clsStaticInfo.dbl(dt.Rows[i]["DebitNote"].ToString());
                    worksheet[ROW, colDebitNoteAmount].NumberFormat = "#,##0.00;(#,##0.00)";
                    worksheet[ROW, colCreditNote].Number = clsStaticInfo.dbl(dt.Rows[i]["CreditNote"].ToString());
                    worksheet[ROW, colCreditNote].NumberFormat = "#,##0.00;(#,##0.00)";
                    worksheet[ROW, colBooksGross].Number = clsStaticInfo.dbl(dt.Rows[i]["BooksGross"].ToString());
                    worksheet[ROW, colBooksGross].NumberFormat = "#,##0.00;(#,##0.00)";

                    worksheet[ROW, colBooksSetOff].Number = clsStaticInfo.dbl(dt.Rows[i]["BooksSetOff"].ToString());
                    worksheet[ROW, colBooksSetOff].NumberFormat = "#,##0.00;(#,##0.00)";

                    worksheet[ROW, colBooksDiscount].Number = clsStaticInfo.dbl(dt.Rows[i]["BooksDiscountAmount"].ToString());
                    worksheet[ROW, colBooksDiscount].NumberFormat = "#,##0.00;(#,##0.00)";
                    worksheet[ROW, colTaxAmount].Number = clsStaticInfo.dbl(dt.Rows[i]["TaxAmount"].ToString());
                    worksheet[ROW, colTaxAmount].NumberFormat = "#,##0.00;(#,##0.00)";

                    worksheet[ROW, colActualBalance].Number = clsStaticInfo.dbl(dt.Rows[i]["ActualBalance"].ToString());
                    worksheet[ROW, colActualBalance].NumberFormat = "#,##0.00;(#,##0.00)";

