        public string GetTaxYearId(string companyId) //string fromDate, string toDate,
        {
            try
            {
                string taxYearId = "";
                var sql = @"SELECT DISTINCT TY.Id TaxCodeYearId
                        FROM [MST].[TaxCodeYear] AS TCY
					    LEFT JOIN [SCS].[TaxYear] AS TY ON TY.Id=TCY.TaxYearId
						LEFT JOIN [SCS].[TaxYearPeriod] AS TYP ON TYP.TaxYearId=TY.Id ";
                DataTable dtTax = _sqlRepository.GetDataTable(sql);
                if (dtTax.Rows.Count > 0)
                {
                    taxYearId = "' '";
                    for (int i = 0; i < dtTax.Rows.Count; i++)
                    {
                        taxYearId += ",'" + dtTax.Rows[i]["TaxCodeYearId"].ToString() + "'";
                    }
                }

                return taxYearId;
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }

        private DataTable GetVendorPayableAgingDetailData(string CompanyGroupId, string CompanyId, string PlantId, Dictionary<string, string> parameters, string taxyearId, string fromDate, string toDate) //string plantName, string fromDate, string toDate,
        {
            string vendorIdLoop = "''";


            for (int i = parameters.Count - 1; i >= 0; i--)
            {
                var item = parameters.ElementAt(i);
                var itemKey = item.Key;
                var itemValue = item.Value;
                vendorIdLoop += ",'" + itemValue + "'";

            }
            var searchDate = "";
            var searchDateODue = "";
            if (fromDate != "" && toDate != "")
            {

                searchDate = "AND ( convert(Date,IV.PostingDate) Between '" + fromDate + @"' and '" + toDate + @"')";
                searchDateODue = "AND ( convert(Date,I.PostingDate) Between '" + fromDate + @"' and '" + toDate + @"')";
            }
            if (fromDate == "" && toDate != "")
            {

                searchDate = "AND ( convert(Date,IV.PostingDate) <= '" + toDate + @"' )";
                searchDateODue = "AND ( convert(Date,I.PostingDate) <= '" + toDate + @"' )";
            }

            string strSql = "";
            strSql = @"select x.* from (

                        SELECT   P.PartyNature,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,EN.UserName Entity,IV.PartyType,IV.PartyId, IV.PartyPlantId,p.code PartyCode, P.UserName PartyName, PP.UserName AS PartyPlantName
										,V.VoucherNo, REPLACE(CONVERT(VARCHAR(11), V.PostingDate, 106), ' ', '-') AS PostingDate,V.DocRefNo InvoiceNo
										, replace (convert(varchar(11),iv.DocDate, 106),'', '-')as DocDate,iv.DocDate  SortDocDate
										, C.Code CurrencyCode
										,IV.BaseNoOfDays, REPLACE(CONVERT(VARCHAR(11), IV.BaseOnDueDate, 106), ' ', '-') AS BaseOnDueDate, REPLACE(CONVERT(VARCHAR(11), IV.ActualDueDate, 106), ' ', '-') AS ActualDueDate
										
										,Days=DATEDIFF(DAY, GETDATE(),IV.BaseOnDueDate)
										,AgingInvoice= case 
													--	when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 OR IV.ActualDueDate IS NULL then 'Overdue'

														when DATEDIFF(DAY, GETDATE(),Iv.ActualDueDate)<-30  OR IV.ActualDueDate IS NULL then 'OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-30  OR IV.ActualDueDate IS NULL then 'OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-15  OR IV.ActualDueDate IS NULL then 'OverDueLessThan15'


															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)=0 then 'Today'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=7 then '1-7'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=30 then '8-30'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=60 then '31-60'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>60 then '60 Onword'
															end
										,AgingSorting= case 
														--when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 OR IV.ActualDueDate IS NULL then '1.Overdue'

														when DATEDIFF(DAY, GETDATE(),Iv.ActualDueDate)<-30  OR IV.ActualDueDate IS NULL then '1.OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-30  OR IV.ActualDueDate IS NULL then '2.OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-15  OR IV.ActualDueDate IS NULL then '3.OverDueLessThan15'


															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)=0 then '4.Today'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=7 then '5.1-7'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=30 then '6.8-30'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=60 then '7.31-60'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>60 then '8.60 Onward'
															end
										, ISNULL(VDC.CrAmount,0)+ISNULL(AID.AdditionalAmount,0) AS Gross,ISNULL(IDND.DNAmount,0) DebitNoteSetOff,ISNULL(IWD.TaxAmount,0) TaxAmount, SetOff=ISNULL(IwV.SetOffBooksAmount, 0)
                                        , ISNULL(ISNULL(VDC.CrAmount,0)+ISNULL(AID.AdditionalAmount,0)-(ISNULL(IwV.SetOffBooksAmount,0)+ISNULL(IWD.TaxAmount,0)+ISNULL(IDND.DNAmount,0)),0) AS Balance								
                                        FROM [TRN].[InvoiceDetail] AS IVD
                                        LEFT JOIN [TRN].[Invoice] AS IV ON IVD.InvoiceId=IV.Id
                                        LEFT JOIN (SELECT SUM(ISNULL(Amount,0)) AdditionalAmount,InvoiceDetailId FROM trn.AdditionalInvoiceDetail   GROUP BY InvoiceDetailId) AS AID ON AID.InvoiceDetailId=IVD.Id
									    LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                                        LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                                        LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                                        LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                                        LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
									    LEFT JOIN [HKP].[PartyPlant] AS PP ON PP.Id=IV.PartyPlantId
                                        LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IVD.Id
                                        LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
                                        LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                                        LEFT JOIN [SCS].[Currency] AS C ON C.Id=IV.CurrencyId
                                        LEFT JOIN [ORG].[Entity] AS EN ON EN.Id=IV.EntityId
										LEFT JOIN (SELECT iwd.InvoiceDetailId,iw.PartyId
                                                    ,SUM(VDC.DrAmount) SetOffBooksAmount
										FROM  [TRN].[InvoiceWriteOffDetail] iwd 
										JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
										LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
										LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
										JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
								        WHERE WV.IsPark=0 AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' ) and  isnull(iw.PaymentSource,'') not in('Tax') and  isnull(iw.SourceType,'') not in('DebitNoteSetOff')
										GROUP BY iwd.InvoiceDetailId,iw.PartyId
										)AS IwV ON IwV.InvoiceDetailId=IVD.Id AND VD.PartyId=IwV.PartyId
                                        
										LEFT JOIN (SELECT wd.InvoiceDetailId,sum(VDC.DrAmount) TaxAmount  FROM TRN.InvoiceWriteOffDetail wd 
											LEFT JOIN  TRN.InvoiceWriteOff w on wd.InvoiceWriteOffId =w.id
											LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=wd.Id
										    LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
                                            JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
								            WHERE WV.IsPark=0 AND  w.PaymentSource='Tax' AND ( convert(Date,W.PostingDate) <= '" + toDate + @"' )
								            group by wd.InvoiceDetailId
								                ) IWD ON IWD.InvoiceDetailId=IVD.Id

                                        LEFT JOIN (SELECT wd.InvoiceDetailId,sum(VDC.DrAmount) DNAmount  FROM TRN.InvoiceWriteOffDetail WD 
								                LEFT JOIN  TRN.InvoiceWriteOff DNW on wd.InvoiceWriteOffId =DNW.id
												LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=wd.Id
												LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
                                                JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
								                WHERE WV.IsPark=0 AND WD.InvoiceDetailId<>'' and DNW.SourceType='DebitNoteSetOff' AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' )
								                group by wd.InvoiceDetailId
								                ) IDND ON IDND.InvoiceDetailId=IVD.Id
										LEFT JOIN MST.PaymentTerm PT ON PT.Id=IV.PaymentTermId

                                        WHERE IV.Archive=0  AND V.IsPark=0 AND IV.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable')
                                        AND IV.CompanyGroupId='" + CompanyGroupId + "' AND IV.CompanyId='" + CompanyId + @"' " + searchDate + @" 
                                        AND ISNULL(ISNULL(VDC.CrAmount,0)+ISNULL(AID.AdditionalAmount,0)-(ISNULL(IwV.SetOffBooksAmount,0)+ISNULL(IWD.TaxAmount,0)+ISNULL(IDND.DNAmount,0)),0)>0
                                        and IV.PartyId in(" + vendorIdLoop + @") 
										--GROUP BY IV.PartyId, PP.UserName,P.UserName

								   UNION ALL
                                    SELECT   P.PartyNature,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,EN.UserName Entity,IV.PartyType,IV.PartyId, IV.PartyPlantId,p.code PartyCode, P.UserName PartyName, PP.UserName AS PartyPlantName
										,V.VoucherNo, REPLACE(CONVERT(VARCHAR(11), V.PostingDate, 106), ' ', '-') AS PostingDate,V.DocRefNo InvoiceNo
										,replace (convert(varchar(11),iv.DocDate, 106),'', '-')as DocDate ,iv.DocDate  SortDocDate
										,C.Code CurrencyCode
										,IV.BaseNoOfDays, REPLACE(CONVERT(VARCHAR(11), IV.BaseOnDueDate, 106), ' ', '-') AS BaseOnDueDate, REPLACE(CONVERT(VARCHAR(11), IV.ActualDueDate, 106), ' ', '-') AS ActualDueDate
										,Days=DATEDIFF(DAY, GETDATE(),IV.BaseOnDueDate)
										
													,AgingInvoice= case 
														--when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 OR IV.ActualDueDate IS NULL then 'Overdue'

														when DATEDIFF(DAY, GETDATE(),Iv.ActualDueDate)<-30  OR IV.ActualDueDate IS NULL then 'OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-30  OR IV.ActualDueDate IS NULL then 'OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-15  OR IV.ActualDueDate IS NULL then 'OverDueLessThan15'


															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)=0 then 'Today'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=7 then '1-7'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=30 then '8-30'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=60 then '31-60'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>60 then '60 Onword'
															end
										,AgingSorting= case 
													--	when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 OR IV.ActualDueDate IS NULL then '1.Overdue'
														when DATEDIFF(DAY, GETDATE(),Iv.ActualDueDate)<-30  OR IV.ActualDueDate IS NULL then '1.OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-30  OR IV.ActualDueDate IS NULL then '2.OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-15  OR IV.ActualDueDate IS NULL then '3.OverDueLessThan15'

															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)=0 then '4.Today'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=7 then '5.1-7'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=30 then '6.8-30'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=60 then '7.31-60'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>60 then '8.60 Onword'
															end
										, ISNULL(VDC.CrAmount,0)+ISNULL(AID.AdditionalAmount,0) AS Gross,ISNULL(IDND.DNAmount,0) DebitNoteSetOff,ISNULL(IWD.TaxAmount,0) TaxAmount,SetOff=ISNULL(IwV.SetOffBooksAmount, 0)
                                        , ISNULL(ISNULL(VDC.CrAmount,0)+ISNULL(AID.AdditionalAmount,0)-(ISNULL(IwV.SetOffBooksAmount,0)+ISNULL(IWD.TaxAmount,0)+ISNULL(IDND.DNAmount,0)),0) AS Balance

                                        FROM [TRN].[InvoiceDetail] AS IVD
                                        LEFT JOIN [TRN].[Invoice] AS IV ON IVD.InvoiceId=IV.Id
                                        LEFT JOIN (SELECT SUM(ISNULL(Amount,0)) AdditionalAmount,InvoiceDetailId FROM trn.AdditionalInvoiceDetail   GROUP BY InvoiceDetailId) AS AID ON AID.InvoiceDetailId=IVD.Id
										LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                                        LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                                        LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                                        LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                                        LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
									    LEFT JOIN [HKP].[PartyPlant] AS PP ON PP.Id=IV.PartyPlantId
                                        LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IVD.Id
                                        LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
                                        LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                                        LEFT JOIN [SCS].[Currency] AS C ON C.Id=IV.CurrencyId
                                        LEFT JOIN [ORG].[Entity] AS EN ON EN.Id=IV.EntityId
										LEFT JOIN (SELECT iwd.InvoiceDetailId,iw.PartyId
                                        ,SUM(VDC.DrAmount) SetOffBooksAmount
										FROM  [TRN].[InvoiceWriteOffDetail] iwd 
										JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
										LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
										LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
										 JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
										WHERE WV.IsPark=0 AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' ) and  isnull(iw.PaymentSource,'') not in('Tax') and  isnull(iw.SourceType,'') not in('DebitNoteSetOff')
										GROUP BY iwd.InvoiceDetailId,iw.PartyId--,iw.PartyPlantId
										)AS IwV ON IwV.InvoiceDetailId=IVD.Id AND VD.PartyId=IwV.PartyId
                                                 LEFT JOIN (SELECT wd.InvoiceDetailId,sum(VDC.DrAmount) TaxAmount  FROM TRN.InvoiceWriteOffDetail wd 
								                LEFT JOIN  TRN.InvoiceWriteOff w on wd.InvoiceWriteOffId =w.id
												LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=wd.Id
										        LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
                                                JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
								                WHERE WV.IsPark=0 AND   w.PaymentSource='Tax' AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' )
								                group by wd.InvoiceDetailId
								                ) IWD ON IWD.InvoiceDetailId=IVD.Id
                                        LEFT JOIN (SELECT wd.InvoiceDetailId,sum(VDC.DrAmount) DNAmount  FROM TRN.InvoiceWriteOffDetail WD 
								                LEFT JOIN  TRN.InvoiceWriteOff DNW on wd.InvoiceWriteOffId =DNW.id
												LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=wd.Id
												LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
                                                JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
								                WHERE WV.IsPark=0 AND   WD.InvoiceDetailId<>'' and DNW.SourceType='DebitNoteSetOff' AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' )
								                group by wd.InvoiceDetailId
								                ) IDND ON IDND.InvoiceDetailId=IVD.Id
                                        LEFT JOIN TRN.InventoryReceive IR ON IR.Id=IV.InventoryReceiveId
										LEFT JOIN MST.PaymentTerm PT ON PT.Id=IV.PaymentTermId
                                        WHERE IV.Archive=0 AND   V.IsPark=0  AND IV.SourceType in ('InventoryPayable','ServicePayable')
                                        AND IV.CompanyGroupId='" + CompanyGroupId + "' AND IV.CompanyId='" + CompanyId + @"' " + searchDate + @"
										AND IR.PurchaseDocumentAcceptanceId IS NULL  and IV.PartyId in(" + vendorIdLoop + @")
                                        AND ISNULL(ISNULL(VDC.CrAmount,0)+ISNULL(AID.AdditionalAmount,0)-(ISNULL(IwV.SetOffBooksAmount,0)+ISNULL(IWD.TaxAmount,0)+ISNULL(IDND.DNAmount,0)),0)>0

                                        UNION ALL
				                        SELECT   P.PartyNature,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,EN.UserName Entity,IV.PartyType,IV.PartyId, IV.PartyPlantId,p.code PartyCode, P.UserName PartyName, PP.UserName AS PartyPlantName
										                        ,V.VoucherNo, REPLACE(CONVERT(VARCHAR(11), V.PostingDate, 106), ' ', '-') AS PostingDate,V.DocRefNo InvoiceNo
										                        ,replace (convert(varchar(11),iv.DocDate, 106),'', '-')as DocDate ,iv.DocDate  SortDocDate
										                        ,C.Code CurrencyCode,0 BaseNoOfDays, REPLACE(CONVERT(VARCHAR(11), IV.PostingDate, 106), ' ', '-') AS BaseOnDueDate, REPLACE(CONVERT(VARCHAR(11), IV.PostingDate, 106), ' ', '-') AS ActualDueDate
																,Days=DATEDIFF(DAY, GETDATE(),IV.PostingDate)
																,AgingInvoice= case 
														when DATEDIFF(DAY, GETDATE(),Iv.PostingDate)<-30  OR IV.PostingDate IS NULL then 'OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.PostingDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)>=-30  OR IV.PostingDate IS NULL then 'OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.PostingDate)<0 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)>=-15  OR IV.PostingDate IS NULL then 'OverDueLessThan15'


															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)=0 then 'Today'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>0 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)<=7 then '1-7'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>7 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)<=30 then '8-30'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>30 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)<=60 then '31-60'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>60 then '60 Onword'
															end
														,AgingSorting= case 
														when DATEDIFF(DAY, GETDATE(),Iv.PostingDate)<-30  OR IV.PostingDate IS NULL then '1.OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.PostingDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)>=-30  OR IV.PostingDate IS NULL then '2.OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.PostingDate)<0 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)>=-15  OR IV.PostingDate IS NULL then '3.OverDueLessThan15'

															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)=0 then '4.Today'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>0 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)<=7 then '5.1-7'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>7 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)<=30 then '6.8-30'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>30 and DATEDIFF(DAY, GETDATE(),IV.PostingDate)<=60 then '7.31-60'
															when DATEDIFF(DAY, GETDATE(),IV.PostingDate)>60 then '8.60 Onword'
															end
										                         , ISNULL(VDC.CrAmount,0) AS Gross,0  DebitNoteSetOff,0 TaxAmount,
                                                                SetOff=ISNULL(IwV.SetOffBooksAmount, 0) , ISNULL(VDC.CrAmount-isnull(IwV.SetOffBooksAmount,0),0) AS Balance
                                        FROM [TRN].[AdjustmentNoteDetail] AS IVD
                                        LEFT JOIN [TRN].[AdjustmentNote] AS IV ON IVD.AdjustmentNoteId=IV.Id
                                        LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                                        LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                                        LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                                        LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                                        LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                                        LEFT JOIN [HKP].[PartyPlant] AS PP ON PP.Id=IV.PartyPlantId
                                        LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.AdjustmentNoteDetailId=IVD.Id
										LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
                                        LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                                        LEFT JOIN [SCS].[Currency] AS C ON C.Id=IV.CurrencyId
                                        LEFT JOIN [ORG].[Entity] AS EN ON EN.Id=IV.EntityId
				                        LEFT JOIN (SELECT iwd.AdjustmentNoteDetailId,iw.PartyId 
                                        ,SUM(VDC.DrAmount) SetOffBooksAmount
										FROM  [TRN].[InvoiceWriteOffDetail] iwd 
										JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
										LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
										LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
										JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
										WHERE WV.IsPark=0 AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"'  )
										GROUP BY iwd.AdjustmentNoteDetailId,iw.PartyId
										)AS IwV ON IwV.AdjustmentNoteDetailId=IVD.Id AND VD.PartyId=IwV.PartyId
                                        WHERE IV.Archive=0 AND   V.IsPark=0 AND IV.PartyType='Vendor' AND IV.SourceType in ('VendorPayment','CreditNote')
                                        AND IV.CompanyGroupId='" + CompanyGroupId + "' AND IV.CompanyId='" + CompanyId + @"' " + searchDate + @"
										AND IV.PartyId in(" + vendorIdLoop + @")
                                        AND (VDC.CrAmount-ISNULL(IwV.SetOffBooksAmount,0))>0
										) x
										order by x.PartyNature,x.PartyGroup,x.PartyName asc";

            return _sqlRepository.GetDataTable(strSql);

        }

        //Pia Chart and donught
        public List<Dictionary<string, object>> GetPartyPaymentStatusAgingPiaChartData(string companyGroupId, string companyId, string plantId)
        {
            var sql = @" 
 
                    SELECT sum(X.ODueMoreThan30NoOfInvoice) ODueMoreThan30NoOfInvoice
					,sum(ISNULL(X.ODueMoreThan30,0)) ODueMoreThan30
					,sum(X.ODueMoreThan15NoOfInvoice) ODueMoreThan15NoOfInvoice
					,sum( ISNULL(X.ODueMoreThan15,0)) ODueMoreThan15
					,sum(X.ODueLessThan15NoOfInvoice) ODueLessThan15NoOfInvoice
					,sum( ISNULL(X.ODueLessThan15,0)) ODueLessThan15
					,sum(X.TodayBalanceNoOfInvoice) TodayBalanceNoOfInvoice
					,sum( ISNULL(X.TodayBalance,0)) TodayBalance
					,sum(X.OneToSevenBalanceNoOfInvoice) OneToSevenBalanceNoOfInvoice
					,sum (ISNULL(X.OneToSevenBalance,0)) OneToSevenBalance
					,sum(X.EightToThirtyBalanceNoOfInvoice) EightToThirtyBalanceNoOfInvoice
					,sum (ISNULL(X.EightToThirtyBalance,0)) EightToThirtyBalance
					,sum(X.ThirtyToSixtyBalanceNoOfInvoice) ThirtyToSixtyBalanceNoOfInvoice
					,sum (ISNULL(X.ThirtyToSixtyBalance,0)) ThirtyToSixtyBalance
					,sum(X.Onword60NoOfInvoice) Onword60NoOfInvoice
					,sum (ISNULL(X.Onword60,0)) Onword60
 
                    FROM (
                    SELECT
					sum(ISNULL(OM30.ODueMoreThan30NoOfInvoice,0)) ODueMoreThan30NoOfInvoice
					,sum(ISNULL(OM30.ODueMoreThan30,0)) ODueMoreThan30
                    ,sum(ISNULL(OM15.ODueMoreThan15NoOfInvoice,0)) ODueMoreThan15NoOfInvoice
					,sum( ISNULL(OM15.ODueMoreThan15,0)) ODueMoreThan15
					,sum( ISNULL(OV.ODueLessThan15NoOfInvoice,0)) ODueLessThan15NoOfInvoice
                    ,sum( ISNULL(OV.ODueLessThan15,0)) ODueLessThan15
				    ,sum( ISNULL(TB.TodayBalanceNoOfInvoice,0)) TodayBalanceNoOfInvoice
                    ,sum (ISNULL(TB.TodayBalance,0)) TodayBalance
					,sum(ISNULL(OTS.OneToSevenBalanceNoOfInvoice,0)) OneToSevenBalanceNoOfInvoice
                    ,sum (ISNULL(OTS.OneToSevenBalance,0)) OneToSevenBalance
                    ,sum( ISNULL(ETT.EightToThirtyBalanceNoOfInvoice,0)) EightToThirtyBalanceNoOfInvoice
				    ,sum (ISNULL(ETT.EightToThirtyBalance,0)) EightToThirtyBalance
					,sum( ISNULL(TTS.ThirtyToSixtyBalanceNoOfInvoice,0)) ThirtyToSixtyBalanceNoOfInvoice
				    ,sum (ISNULL(TTS.ThirtyToSixtyBalance,0)) ThirtyToSixtyBalance
				    ,sum( ISNULL(O60.Onword60NoOfInvoice,0)) Onword60NoOfInvoice
                    ,sum (ISNULL(O60.Onword60,0)) Onword60

                    FROM [TRN].[Invoice] AS IV 
                    LEFT JOIN [TRN].[Voucher] AS V ON V.Id=IV.VoucherId

					LEFT JOIN (SELECT count(i.PartyId) ODueMoreThan30NoOfInvoice,I.Id,SUM(ISNULL(IVD.InvoiceBooksAmount,0))-SUM(ISNULL(IVD.SetOffBooksAmount,0)) AS ODueMoreThan30 FROM TRN.Invoice I
										JOIN (select IDE.InvoiceId,VD.PartyId
										,SUM(VDC.CrAmount) InvoiceBooksAmount ,SUM(ISNULL(IwV.SetOffBooksAmount,0)) SetOffBooksAmount
											FROM  [TRN].[InvoiceDetail] IDE
											LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IDE.Id
											LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
											LEFT JOIN [TRN].[Voucher] AS VI ON VI.Id=VD.VoucherId
											LEFT JOIN (SELECT iwd.InvoiceDetailId,VD.PartyId,SUM(VDC.DrAmount) SetOffBooksAmount
												FROM  [TRN].[InvoiceWriteOffDetail] iwd 
												JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
												LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
												LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
												 JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
												WHERE WV.IsPark=0 
												GROUP BY iwd.InvoiceDetailId,VD.PartyId
												)AS IwV ON IwV.InvoiceDetailId=IDE.Id AND VD.PartyId=IwV.PartyId
											WHERE  VI.Archive=0  AND VI.IsPark=0 and VD.PartyType='Vendor' 
											GROUP BY IDE.InvoiceId,VD.PartyId
									 ) AS IVD ON IVD.InvoiceId=I.Id AND IVD.PartyId=I.PartyId
					 WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<-30  AND ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0)>0
					 and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable','InventoryPayable','ServicePayable') GROUP BY I.Id) OM30 ON OM30.Id=IV.Id

                    LEFT JOIN (SELECT count(i.PartyId) ODueMoreThan15NoOfInvoice,I.Id,SUM(ISNULL(IVD.InvoiceBooksAmount,0))-SUM(ISNULL(IVD.SetOffBooksAmount,0)) AS ODueMoreThan15 FROM TRN.Invoice I
                                        JOIN (select IDE.InvoiceId,VD.PartyId
										,SUM(VDC.CrAmount) InvoiceBooksAmount ,SUM(ISNULL(IwV.SetOffBooksAmount,0)) SetOffBooksAmount
											FROM  [TRN].[InvoiceDetail] IDE
											LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IDE.Id
											LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
											LEFT JOIN [TRN].[Voucher] AS VI ON VI.Id=VD.VoucherId
											LEFT JOIN (SELECT iwd.InvoiceDetailId,VD.PartyId,SUM(VDC.DrAmount) SetOffBooksAmount
												FROM  [TRN].[InvoiceWriteOffDetail] iwd 
												JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
												LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
												LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
												 JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
												WHERE WV.IsPark=0 
												GROUP BY iwd.InvoiceDetailId,VD.PartyId
												)AS IwV ON IwV.InvoiceDetailId=IDE.Id AND VD.PartyId=IwV.PartyId
											WHERE  VI.Archive=0  AND VI.IsPark=0 and VD.PartyType='Vendor' 
											GROUP BY IDE.InvoiceId,VD.PartyId
									 ) AS IVD ON IVD.InvoiceId=I.Id AND IVD.PartyId=I.PartyId
                    WHERE DATEDIFF(DAY, GETDATE(),I.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),I.ActualDueDate)>=-30 AND ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0)>0
                    and I.SourceType in ('VendorInvoice','PurchaseDocAcceptance','SuspensePayable','EmployeePayable','InventoryPayable','ServicePayable') GROUP BY I.Id) OM15 ON OM15.Id=IV.Id

                    LEFT JOIN (SELECT count(i.PartyId) ODueLessThan15NoOfInvoice,I.Id,SUM(ISNULL(IVD.InvoiceBooksAmount,0))-SUM(ISNULL(IVD.SetOffBooksAmount,0)) AS ODueLessThan15 FROM TRN.Invoice I
                                        JOIN (select IDE.InvoiceId,VD.PartyId
										,SUM(VDC.CrAmount) InvoiceBooksAmount ,SUM(ISNULL(IwV.SetOffBooksAmount,0)) SetOffBooksAmount
											FROM  [TRN].[InvoiceDetail] IDE
											LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IDE.Id
											LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
											LEFT JOIN [TRN].[Voucher] AS VI ON VI.Id=VD.VoucherId
