        #region GRN with out invoice
        public IEnumerable<object> GetInvoiceWithOutGRNDataList(string companyGroupId, string companyId, string plantId, string toDate)

        {
            try
            {
                var sql = @"select x.* from (

                        SELECT   IV.PartyType,IV.PartyId, IV.PartyPlantId,p.code PartyCode, P.UserName PartyName, PP.UserName AS PartyPlantName
										,isnull( V.VoucherNo,'')VoucherNo,IVD.InvoiceId,VD.VoucherId,isnull( PDA.InvoiceNo,'')InvoiceNo
										 ,PurchaseLCNo= STUFF((select distinct ','+XVD.LCRef from
														dbo.PurchaseLC XVD Left join TRN.PurchasedocAcceptance AS XP ON XP.PurchaseLCId=XVD.Id
													where	PDA.Id=XP.Id  for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '')
										,PONo= isnull( STUFF((select distinct ','+xpomap.POId from
											dbo.PurchaseLC XVD Left join TRN.PurchasedocAcceptance AS XP ON XP.PurchaseLCId=XVD.Id
											LEFT JOIN trn.PurchaseDocAcceptancePOMap xpomap on xpomap.PurchaseDocAcceptanceId=xp.Id
										where	PDA.Id=XP.Id  for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, ''),'')
                                        , REPLACE(CONVERT(VARCHAR(11), V.PostingDate, 106), ' ', '-') AS PostingDate,V.DocRefNo
										, replace (convert(varchar(11),iv.DocDate, 106),'', '-')as DocDate,iv.DocDate  SortDocDate
										, C.Code CurrencyCode
										,IV.BaseNoOfDays, REPLACE(CONVERT(VARCHAR(11), IV.BaseOnDueDate, 106), ' ', '-') AS BaseOnDueDate, REPLACE(CONVERT(VARCHAR(11), IV.ActualDueDate, 106), ' ', '-') AS ActualDueDate
										
										,Days=DATEDIFF(DAY, GETDATE(),IV.BaseOnDueDate)
										,AgingInvoice= case 
													--	when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 OR IV.ActualDueDate IS NULL then 'Overdue'

														when DATEDIFF(DAY, GETDATE(),Iv.ActualDueDate)<-30  OR IV.ActualDueDate IS NULL then 'OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-30  OR IV.ActualDueDate IS NULL then 'OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-15  OR IV.ActualDueDate IS NULL then 'OverDueLessThan15'


															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)=0 then 'Today'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=7 then '1-7'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=30 then '8-30'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=60 then '31-60'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>60 then '60 Onword'
															end
										,AgingSorting= case 
														--when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 OR IV.ActualDueDate IS NULL then '1.Overdue'

														when DATEDIFF(DAY, GETDATE(),Iv.ActualDueDate)<-30  OR IV.ActualDueDate IS NULL then '1.OverDueMoreThan30'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<-15 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-30  OR IV.ActualDueDate IS NULL then '2.OverDueMoreThan15'
														when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>=-15  OR IV.ActualDueDate IS NULL then '3.OverDueLessThan15'


															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)=0 then '4.Today'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>0 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=7 then '5.1-7'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>7 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=30 then '6.8-30'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>30 and DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)<=60 then '7.31-60'
															when DATEDIFF(DAY, GETDATE(),IV.ActualDueDate)>60 then '8.60 Onward'
															end

										, ISNULL(IVD.NetAmount,0) AS Gross
										,0 DebitNoteAmount
										,isnull( IWD.TaxAmount ,0)TaxAmount,
                                         SetOff=ISNULL(IRD.TotalMaterialTranAmount, 0) 
										 , ISNULL(IVD.NetAmount-ISNULL(IRD.TotalMaterialTranAmount, 0),0) AS Balance

										,CC.CompanyCurrencyRate
										,ISNULL(IVD.NetAmount*CC.CompanyCurrencyRate,0) AS BooksGross
								    	,0 DebitNoteBooksAmount
										,isnull(IWD.TaxAmount* CC.CompanyCurrencyRate,0) BooksTaxAmount
										,ISNULL (ISNULL(IRD.TotalMaterialTranAmount, 0)*CC.CompanyCurrencyRate,0)   AS BooksSetOff
										,ISNULL((IVD.NetAmount*CC.CompanyCurrencyRate)-(ISNULL(IRD.TotalMaterialTranAmount, 0)*CC.CompanyCurrencyRate),0) AS BooksBalance
										,ISNULL (ISNULL(IDND.WriteOffAmount, 0)*CC.CompanyCurrencyRate,0)   AS BooksWriteOffAmount
										,ISNULL((IVD.NetAmount*CC.CompanyCurrencyRate)-(ISNULL(IDND.WriteOffAmount, 0)*CC.CompanyCurrencyRate),0) AS BooksInvoiceBalance
                                        FROM [TRN].[InvoiceDetail] AS IVD
                                        LEFT JOIN [TRN].[Invoice] AS IV ON IVD.InvoiceId=IV.Id
										LEFT JOIN TRN.PurchasedocAcceptance AS PDA ON IV.PurchaseDocAcceptanceId=PDA.Id
									    LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
									    LEFT JOIN [HKP].[PartyPlant] AS PP ON PP.Id=IV.PartyPlantId
                                        LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IVD.Id
                                        LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                                        LEFT JOIN [SCS].[Currency] AS C ON C.Id=IV.CurrencyId
                                        LEFT JOIN [ORG].[Entity] AS EN ON EN.Id=IV.EntityId
										LEFT JOIN (SELECT PurchaseDocumentAcceptanceId,SUM(MaterialTranAmount) MaterialTranAmount
											,SUM(TotalMaterialTranAmount) TotalMaterialTranAmount,SUM(ChargesTranAmount) ChargesTranAmount
											,SUM(ChargesTaxTranAmount) ChargesTaxTranAmount
											FROM TRN.InventoryReceiveDetail GROUP BY PurchaseDocumentAcceptanceId) AS IRD ON IRD.PurchaseDocumentAcceptanceId=PDA.Id
                                        LEFT JOIN (SELECT wd.InvoiceDetailId,sum(wd.Amount) TaxAmount  FROM TRN.InvoiceWriteOffDetail wd 
								        LEFT JOIN  TRN.InvoiceWriteOff w on wd.InvoiceWriteOffId =w.id
								            where w.PaymentSource='Tax'
								            group by wd.InvoiceDetailId
								                ) IWD ON IWD.InvoiceDetailId=IVD.Id

                                         LEFT JOIN (SELECT wd.InvoiceDetailId,sum(wd.Amount) WriteOffAmount  FROM TRN.InvoiceWriteOffDetail WD 
								                LEFT JOIN  TRN.InvoiceWriteOff DNW on wd.InvoiceWriteOffId =DNW.id
								                where WD.InvoiceDetailId<>'' and DNW.PaymentSource<>'Tax'
								                group by wd.InvoiceDetailId
								                ) IDND ON IDND.InvoiceDetailId=IVD.Id
										LEFT JOIN MST.PaymentTerm PT ON PT.Id=IV.PaymentTermId
										LEFT JOIN (
										SELECT VDC.ParallelCurrencyId AS CompanyCurrencyId, VDC.FromCurrencyId AS CompanyFromCurrencyId, VDC.ToCurrencyId,
										VDC.ToCurrencyRate AS CompanyCurrencyRate, VDC.ToCurrencyConversion AS CompanyCurrencyConversion, VDC.DrAmount AS CompanyCurrencyAmount, VDC.VoucherDetailId
										FROM [TRN].[VoucherDetailCurrency] AS VDC
										JOIN [SCS].[CompanyParallelCurrency] AS CPC ON CPC.CurrencyId=VDC.ParallelCurrencyId
										WHERE CPC.ParallelCurrencyType='CompanyCurrency' AND CPC.CompanyId='" + companyId + @"'
									) AS CC ON CC.VoucherDetailId=VD.Id
									
                                        WHERE IV.Archive=0 AND V.IsPark=0 AND IVD.IsBlock=0 AND IV.SourceType in ('PurchaseDocAcceptance')
                                        AND IV.CompanyGroupId='" + companyGroupId + "' AND IV.CompanyId='" + companyId + @"' AND IV.PlantId='" + plantId + @"'
                                       
                                        and IV.PostingDate <= '" + toDate + @"'
										--GROUP BY IV.PartyId, IV.PartyPlantId, PP.UserName,P.UserName
										) x
                                        where x.Balance>0
										order by x.SortDocDate asc";
                return _sqlRepository.GetDataCollection(sql);

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }

        #endregion 

        #region Party Status
        public IEnumerable<object> GetPartyStatusDataList(string companyGroupId, string companyId, string plantId, string toDate)

        {
            try
            {
                var sql = @"SELECT y.* ,CASE WHEN y.ToBePayment>0 OR ToBeReceived>0 THEN 'Yes' ELSE 'No' END PaymentApplicable
            ,CASE WHEN (SELECT COUNT(Id) FROM HKP.CompanyParty WHERE PartyId=y.PartyId AND  PartyType='Vendor')>0 THEN 'Yes' ELSE 'No' END IsVendor
            ,CASE WHEN (SELECT COUNT(Id) FROM HKP.CompanyParty WHERE PartyId=y.PartyId AND PartyType='Customer')>0 THEN 'Yes' ELSE 'No' END IsCustomer
            FROM(Select x.PartyNature,x.PartyGroup,x.PartyCategory,x.PartySubCategory,x.ResponsiblePerson,x.PartyId,x.PartyName,round(sum(x.VendorAdvance),2) VendorAdvance,round(sum(x.VendorDebitNote),2) VendorDebitNote,round(sum(x.Payable),2) Payable
                ,round(sum(x.CustomerAdvance),2) CustomerAdvance,round(sum(x.CustomerCreditNote),2) CustomerCreditNote,round(sum(x.Receivable),2) Receivable
                ,ToBePayment=Case when round((sum(x.Payable)-sum(x.VendorAdvance)-sum(x.VendorDebitNote)-sum(x.Receivable)+sum(x.CustomerAdvance)+sum(x.CustomerCreditNote)),2)>0 then round((sum(x.Payable)-sum(x.VendorAdvance)-sum(x.VendorDebitNote)-sum(x.Receivable)+sum(x.CustomerAdvance)+sum(x.CustomerCreditNote)),2) else 0 end
                ,ToBeReceived=Case when round((sum(x.Receivable)-sum(x.Payable)+sum(x.VendorAdvance)+sum(x.VendorDebitNote)-sum(x.CustomerAdvance)-sum(x.CustomerCreditNote)),2)>0 then round((sum(x.Receivable)-sum(x.Payable)+sum(x.VendorAdvance)+sum(x.VendorDebitNote)-sum(x.CustomerAdvance)-sum(x.CustomerCreditNote)),2) else 0 end
                ,ISNULL((SELECT  round(SUM(ISNULL(CC.CompanyCurrencyCrAmount, 0)) - SUM(ISNULL(CC.CompanyCurrencyDrAmount, 0)),2) AS VendorLedgerBalanceAmount
                    FROM [TRN].[VoucherDetail] AS VD
                    LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                    LEFT JOIN (SELECT VDC.VoucherDetailId, VDC.DrAmount AS CompanyCurrencyDrAmount, VDC.CrAmount AS CompanyCurrencyCrAmount
	                    FROM [TRN].[VoucherDetailCurrency] AS VDC) AS CC ON CC.VoucherDetailId=VD.Id
                    WHERE V.Archive=0 AND V.IsPark=0 AND V.PlantId='" + plantId + @"' AND convert(Date,V.PostingDate) <= '" + toDate + @"' AND VD.PartyId=X.PartyId AND VD.PartyType IN ('Vendor') 
					GROUP BY VD.PartyId),0) VendorLedgerBalanceAmount
                ,ISNULL((SELECT  round(SUM(ISNULL(CC.CompanyCurrencyDrAmount, 0)) - SUM(ISNULL(CC.CompanyCurrencyCrAmount, 0)),2) AS CustomerLedgerBalanceAmount
                    FROM [TRN].[VoucherDetail] AS VD
                    LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
                    LEFT JOIN (SELECT VDC.VoucherDetailId, VDC.DrAmount AS CompanyCurrencyDrAmount, VDC.CrAmount AS CompanyCurrencyCrAmount
	                    FROM [TRN].[VoucherDetailCurrency] AS VDC) AS CC ON CC.VoucherDetailId=VD.Id
                    WHERE V.Archive=0 AND V.IsPark=0 AND V.PlantId='" + plantId + @"' AND convert(Date,V.PostingDate) <= '" + toDate + @"' AND VD.PartyId=X.PartyId AND VD.PartyType IN ('Customer') 
					GROUP BY VD.PartyId),0) CustomerLedgerBalanceAmount
                ,round(sum(x.RemainingPOPayable),2) RemainingPOAmount
        from (
        SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
                , 0 VendorAdvance, 0 VendorDebitNote
				, ISNULL(IVD.InvoiceBooksAmount-IVD.SetOffBooksAmount,0) AS Payable
				, ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IV.WrittenOffAmount*IV.CompanyCurrencyRate,0) AS ActualPayable
				,0 CustomerAdvance,0 CustomerCreditNote,0 Receivable,0 ActualReceivable ,0 RemainingPOPayable
				 FROM [TRN].[Invoice] AS IV 
                 JOIN (select IDE.InvoiceId,VD.PartyId,SUM(VDC.CrAmount) + SUM(ISNULL(AID.AdditionalAmount,0)) InvoiceBooksAmount ,ISNULL(IwV.SetOffBooksAmount,0) SetOffBooksAmount
						FROM  [TRN].[InvoiceDetail] IDE
                        LEFT JOIN (SELECT SUM(ISNULL(Amount,0)) AdditionalAmount,InvoiceDetailId FROM trn.AdditionalInvoiceDetail   GROUP BY InvoiceDetailId) AS AID ON AID.InvoiceDetailId=IDE.Id
						LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IDE.Id
						LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
						LEFT JOIN [TRN].[Voucher] AS VI ON VI.Id=VD.VoucherId
						LEFT JOIN (SELECT iwd.InvoiceDetailId,iw.PartyId
						,ISNULL(SUM(VDC.DrAmount),0) SetOffBooksAmount
							FROM  [TRN].[InvoiceWriteOffDetail] iwd 
							JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
							LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
							LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
							 JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
							WHERE WV.IsPark=0 AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' )
							GROUP BY iwd.InvoiceDetailId,iw.PartyId
							)AS IwV ON IwV.InvoiceDetailId=IDE.Id AND VD.PartyId=IwV.PartyId
						WHERE VI.IsPark=0 
						GROUP BY IDE.InvoiceId,VD.PartyId,IwV.SetOffBooksAmount
				 ) AS IVD ON IVD.InvoiceId=IV.Id AND IVD.PartyId=IV.PartyId
                LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                LEFT JOIN [TRN].[Voucher] AS V ON V.Id=IV.VoucherId
				 WHERE IV.Archive=0 AND  V.IsPark=0  AND IV.SourceType in ('VendorInvoice','InventoryPayable','PurchaseDocAcceptance','SuspensePayable','ServicePayable','EmployeePayable')
               AND IV.CompanyGroupId='" + companyGroupId + "'   AND IV.CompanyId='" + companyId + @"' AND IV.PlantId='" + plantId + @"' AND ( convert(Date,IV.PostingDate) <= '" + toDate + @"' )
                and ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0)>0

                UNION ALL
				SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
                , 0 VendorAdvance, 0 VendorDebitNote
				, ISNULL(VDC.CrAmount-ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0),0) AS Payable
				, 0 ActualPayable,0 CustomerAdvance,0 CustomerCreditNote,0 Receivable,0 ActualReceivable ,0 RemainingPOPayable
                FROM [TRN].[AdjustmentNoteDetail] AS IVD
                LEFT JOIN [TRN].[AdjustmentNote] AS IV ON IVD.AdjustmentNoteId=IV.Id
                LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.AdjustmentNoteDetailId=IVD.Id
                LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
                LEFT JOIN [TRN].[Voucher] AS V ON V.Id=VD.VoucherId
				LEFT JOIN (select SUM(ISNULL(VDCW.DrAmount,0))AdjustmentNoteWriteOffBooksAmount,AdjustmentNoteId from [TRN].[InvoiceWriteOffDetail] IWD
										INNER JOIN [TRN].[InvoiceWriteOff] IW ON IW.Id=IWD.InvoiceWriteOffId
										INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.InvoiceWriteOffDetailId=IWD.Id
										 INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
										where IW.IsPark=0 AND IWD.AdjustmentNoteId is not null AND ( convert(Date,IW.PostingDate) <= '" + toDate + @"')
										GROUP BY  IWD.AdjustmentNoteId)W ON W.AdjustmentNoteId=IVD.AdjustmentNoteId
                WHERE IV.Archive=0  AND V.IsPark=0 AND IV.PartyType='Vendor' AND IV.SourceType in ('VendorPayment','CreditNote')
                    AND ISNULL(VDC.CrAmount,0)-ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0)>0
               AND IV.CompanyGroupId='" + companyGroupId + "'   AND IV.CompanyId='" + companyId + @"' AND IV.PlantId='" + plantId + @"' AND ( convert(Date,IV.PostingDate) <= '" + toDate + @"' )


                UNION ALL
				 SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
                , ISNULL(VDCA.DrAmount,0)+ISNULL(ADDW.AdditionalAdvanceAmount,0)- ISNULL(AW.AdvanceWriteOffBooksAmount,0) VendorAdvance
				, 0 VendorDebitNote, 0 Payable, 0 ActualPayable
				,0 CustomerAdvance,0 CustomerCreditNote,0 Receivable,0 ActualReceivable ,0 RemainingPOPayable
				FROM TRN.Advance A
				LEFT JOIN [HKP].[Party] AS P ON P.Id=A.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
				INNER JOIN  [TRN].[AdvanceDetail] AD ON AD.AdvanceId=A.Id
				INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdvanceDetailId=AD.Id
				INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCA ON VDCA.VoucherDetailId=VDA.Id
                LEFT JOIN (select SUM(VDCW.CrAmount)AdvanceWriteOffBooksAmount,AdvanceId from [TRN].[AdvanceWriteOffDetail] AWD
				        INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.AdvanceWriteOffDetailId=AWD.Id
				        INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
                        LEFT JOIN [TRN].[AdvanceWriteOff] AW ON AW.Id=AWD.AdvanceWriteOffId 
				        LEFT JOIN [TRN].[Voucher] VW ON VW.Id=AW.VoucherId 
				        WHERE VW.IsPark=0 AND VW.Archive=0
                        and ( convert(Date,AW.PostingDate) <= '" + toDate + @"')
                        GROUP BY AdvanceId)AW ON AW.AdvanceId=A.Id
                LEFT JOIN (select SUM(VDCW.DrAmount)AdditionalAdvanceAmount,AdvanceId from [TRN].[AdvanceWriteOffDetail] AWD
				        INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.AdvanceWriteOffDetailId=AWD.Id
				        INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
                        LEFT JOIN [TRN].[AdvanceWriteOff] AW ON AW.Id=AWD.AdvanceWriteOffId 
				        LEFT JOIN [TRN].[Voucher] VW ON VW.Id=AW.VoucherId 
				        WHERE VW.IsPark=0 AND VW.Archive=0
                        and ( convert(Date,AW.PostingDate) <= '" + toDate + @"' and AWD.IsAdditionalAdvance=1)
                        GROUP BY AdvanceId)ADDW ON ADDW.AdvanceId=A.Id
                where A.IsPark=0 AND A.PlantId='" + plantId + @"' and A.SourceType='VendorAdvance'  and A.PartyType='Vendor' 
				AND ( convert(Date,A.PostingDate) <= '" + toDate + @"' ) and ISNULL(VDCA.DrAmount,0)+ISNULL(ADDW.AdditionalAdvanceAmount,0) - ISNULL(AW.AdvanceWriteOffBooksAmount,0)>0
                
                UNION ALL
				 SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
				 ,0 VendorAdvance
                , ( ISNULL(VDC.DrAmount,0)- ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0)) VendorDebitNote
				, 0 Payable, 0 ActualPayable,0 CustomerAdvance,0 CustomerCreditNote,0 Receivable,0 ActualReceivable ,0 RemainingPOPayable
				FROM [TRN].[AdjustmentNote] A
				LEFT JOIN [HKP].[Party] AS P ON P.Id=A.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
				INNER JOIN  [TRN].[AdjustmentNoteDetail] AD ON AD.AdjustmentNoteId=A.Id
                INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdjustmentNoteDetailId=AD.Id
                INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VDA.Id
				LEFT JOIN (select SUM(ISNULL(VDCW.CrAmount,0))AdjustmentNoteWriteOffBooksAmount,AdjustmentNoteId from [TRN].[InvoiceWriteOffDetail] IWD
								INNER JOIN [TRN].[InvoiceWriteOff] IW ON IW.Id=IWD.InvoiceWriteOffId
								INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.InvoiceWriteOffDetailId=IWD.Id
								INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
								where IW.IsPark=0 AND IWD.AdjustmentNoteId is not null AND ( convert(Date,IW.PostingDate) <= '" + toDate + @"' )
								GROUP BY  IWD.AdjustmentNoteId)W ON W.AdjustmentNoteId=AD.AdjustmentNoteId
                where A.PlantId='" + plantId + @"' and VDA.PartyType='Vendor' and A.SourceType in('DebitNote','InventoryReturnPayable')  AND A.IsPark=0
				AND ( convert(Date,A.PostingDate) <= '" + toDate + @"' ) AND ( ISNULL(VDC.DrAmount,0)- ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0))>0

				UNION ALL
				SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
                ,0 VendorAdvance,0 DebitNote,0 Payable,0 ActualPayable,0 CustomerAdvance,0 CustomerCreditNote
				,ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0) AS Receivable
				,ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IV.WrittenOffAmount*IV.CompanyCurrencyRate,0) AS  ActualReceivable
                ,0 RemainingPOPayable
				 FROM [TRN].[Invoice] AS IV 
                 JOIN (select IDE.InvoiceId,VD.PartyId,SUM(VDC.DrAmount) InvoiceBooksAmount ,ISNULL(IwV.SetOffBooksAmount,0) SetOffBooksAmount
						FROM  [TRN].[InvoiceDetail] IDE
						LEFT JOIN [TRN].[VoucherDetail] AS VD ON VD.InvoiceDetailId=IDE.Id
						LEFT JOIN [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VD.Id
						LEFT JOIN [TRN].[Voucher] AS VI ON VI.Id=VD.VoucherId
						LEFT JOIN (SELECT iwd.InvoiceDetailId,iw.PartyId ,ISNULL(SUM(VDC.CrAmount),0) SetOffBooksAmount
							FROM  [TRN].[InvoiceWriteOffDetail] iwd 
							JOIN TRN.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
							LEFT JOIN TRN.VoucherDetail VD ON VD.InvoiceWriteOffDetailId=iwd.Id
							LEFT JOIN TRN.VoucherDetailCurrency VDC ON VDC.VoucherDetailId=VD.Id
							 JOIN TRN.Voucher WV ON WV.Id=VD.VoucherId
							WHERE WV.IsPark=0 AND ( convert(Date,WV.PostingDate) <= '" + toDate + @"' )
							GROUP BY iwd.InvoiceDetailId,iw.PartyId
							)AS IwV ON IwV.InvoiceDetailId=IDE.Id AND VD.PartyId=IwV.PartyId
						WHERE VI.IsPark=0 and VD.PartyType='Customer' --AND VD.PartyId='202017395'
						GROUP BY IDE.InvoiceId,VD.PartyId,IwV.SetOffBooksAmount
				 ) AS IVD ON IVD.InvoiceId=IV.Id AND IVD.PartyId=IV.PartyId
                LEFT JOIN [HKP].[Party] AS P ON P.Id=IV.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                LEFT JOIN [TRN].[Voucher] AS V ON V.Id=IV.VoucherId
				WHERE IV.Archive=0 AND  V.IsPark=0  AND IV.SourceType in ('CustomerInvoice','CustomerBanksReceipt','CustomerReceipt','SalesInvoice','InventorySales') 
               AND IV.CompanyGroupId='" + companyGroupId + "'   AND IV.CompanyId='" + companyId + @"' AND IV.PlantId='" + plantId + @"' AND ( convert(Date,IV.PostingDate) <= '" + toDate + @"' )
                and ISNULL(IVD.InvoiceBooksAmount,0)-ISNULL(IVD.SetOffBooksAmount,0)>0
				
                UNION ALL
				SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
				,0 VendorAdvance ,0 VendorDebitNote,0 Payable,0 ActualPayable,0 CustomerAdvance,0 CustomerCreditNote
				,( ISNULL(VDC.DrAmount,0)- ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0)) Receivable
				,0 ActualReceivable ,0 RemainingPOPayable
				FROM [TRN].[AdjustmentNote] A
				LEFT JOIN [HKP].[Party] AS P ON P.Id=A.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
				INNER JOIN  [TRN].[AdjustmentNoteDetail] AD ON AD.AdjustmentNoteId=A.Id
                INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdjustmentNoteDetailId=AD.Id
                INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VDA.Id
				LEFT JOIN (select SUM(ISNULL(VDCW.CrAmount,0))AdjustmentNoteWriteOffBooksAmount,AdjustmentNoteId from [TRN].[InvoiceWriteOffDetail] IWD
								INNER JOIN [TRN].[InvoiceWriteOff] IW ON IW.Id=IWD.InvoiceWriteOffId
								INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.InvoiceWriteOffDetailId=IWD.Id
								INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
								WHERE IW.IsPark=0 AND IWD.AdjustmentNoteId is not null AND ( convert(Date,IW.PostingDate) <= '" + toDate + @"' )
								GROUP BY  IWD.AdjustmentNoteId)W ON W.AdjustmentNoteId=AD.AdjustmentNoteId
                where A.PlantId='" + plantId + @"' and VDA.PartyType='Customer' and A.SourceType in('DebitNote','CustomerReceipt')  AND A.IsPark=0
				AND ( convert(Date,A.PostingDate) <= '" + toDate + @"' ) AND ( ISNULL(VDC.DrAmount,0)- ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0))>0

                UNION ALL
				 SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
                ,0 VendorAdvance,0 DebitNote,0 Payable,0 ActualPayable
				,ISNULL(VDCA.CrAmount,0)- ISNULL(AW.AdvanceWriteOffBooksAmount,0) CustomerAdvance
                ,0 CustomerCreditNote,0 Receivable,0 ActualReceivable ,0 RemainingPOPayable
				FROM TRN.Advance A
				LEFT JOIN [HKP].[Party] AS P ON P.Id=A.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
				INNER JOIN  [TRN].[AdvanceDetail] AD ON AD.AdvanceId=A.Id
				INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdvanceDetailId=AD.Id
				INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCA ON VDCA.VoucherDetailId=VDA.Id
                LEFT JOIN (select SUM(VDCW.DrAmount)AdvanceWriteOffBooksAmount,AdvanceId from [TRN].[AdvanceWriteOffDetail] AWD
				INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.AdvanceWriteOffDetailId=AWD.Id
				INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
                LEFT JOIN [TRN].[AdvanceWriteOff] AW ON AW.Id=AWD.AdvanceWriteOffId WHERE AW.IsPark=0 AND AW.Archive=0 
                AND ( convert(Date,AW.PostingDate) <= '" + toDate + @"') GROUP BY AdvanceId)AW ON AW.AdvanceId=A.Id
                WHERE A.PlantId='" + plantId + @"' and A.SourceType='CustomerAdvance'  AND A.IsPark=0
				AND ( convert(Date,A.PostingDate) <= '" + toDate + @"' ) 
				and (ISNULL(VDCA.CrAmount,0)- ISNULL(AW.AdvanceWriteOffBooksAmount,0))>0

                UNION ALL
				SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
				,0 VendorAdvance ,0 VendorDebitNote,0 Payable,0 ActualPayable,0 CustomerAdvance
                ,( ISNULL(VDC.CrAmount,0)- ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0)) CustomerCreditNote
                ,0 Receivable,0 ActualReceivable ,0 RemainingPOPayable
				FROM [TRN].[AdjustmentNote] A
				LEFT JOIN [HKP].[Party] AS P ON P.Id=A.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
				INNER JOIN  [TRN].[AdjustmentNoteDetail] AD ON AD.AdjustmentNoteId=A.Id
                INNER JOIN  [TRN].[VoucherDetail] VDA ON VDA.AdjustmentNoteDetailId=AD.Id
                INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDC ON VDC.VoucherDetailId=VDA.Id
				LEFT JOIN (select SUM(ISNULL(VDCW.DrAmount,0))AdjustmentNoteWriteOffBooksAmount,AdjustmentNoteId from [TRN].[InvoiceWriteOffDetail] IWD
								INNER JOIN [TRN].[InvoiceWriteOff] IW ON IW.Id=IWD.InvoiceWriteOffId
								INNER JOIN  [TRN].[VoucherDetail] VDW ON VDW.InvoiceWriteOffDetailId=IWD.Id
								INNER JOIN  [TRN].[VoucherDetailCurrency] AS VDCW ON VDCW.VoucherDetailId=VDW.Id
								where IW.IsPark=0 AND IWD.AdjustmentNoteId is not null AND ( convert(Date,IW.PostingDate) <= '" + toDate + @"' )
								GROUP BY  IWD.AdjustmentNoteId)W ON W.AdjustmentNoteId=AD.AdjustmentNoteId
                where A.PlantId='" + plantId + @"' and VDA.PartyType='Customer' and A.SourceType in('CreditNote')  AND A.IsPark=0
				AND ( convert(Date,A.PostingDate) <= '" + toDate + @"' ) AND ( ISNULL(VDC.CrAmount,0)- ISNULL(W.AdjustmentNoteWriteOffBooksAmount,0))>0
                
                UNION ALL
                SELECT P.Id PartyId,P.Code PartyCode,PG.UserName PartyGroup,PC.UserName PartyCategory,PSC.UserName PartySubCategory,E.EmployeeName ResponsiblePerson,P.PartyNature,P.UserName PartyName
                ,0 VendorAdvance,0 VendorDebitNote,0 Payable,0 ActualPayable,0 CustomerAdvance,0 CustomerCreditNote,0 Receivable,0 ActualReceivable 
                ,ISNULL(pod.BaseAmount,0)-ISNULL(IRD.GRNAmount,0) RemainingPOPayable
                from trn.PurchaseOrderdetail pod 
                join trn.PurchaseOrder po ON po.Id=pod.InventoryReceiveId
                left join(select sum(ISNULL(TotalMaterialBooksCurrencyAmount,0)) GRNAmount,PodetailsId from trn.InventoryReceiveDetail IRD 
                left join trn.InventoryReceive IR ON IR.Id=IRD.InventoryReceiveId
                group by IRD.PODetailsId
                )IRD ON IRD.PodetailsId=pod.id
                left join hkp.Party P ON P.Id=po.PartyId
                LEFT JOIN [HKP].[PartyGroup] AS PG ON PG.Id=P.PartyGroupId
                LEFT JOIN [HKP].[PartyCategory] AS PC ON PC.Id=P.PartyCategoryId
                LEFT JOIN [HKP].[PartySubCategory] AS PSC ON PSC.Id=P.PartySubCategoryId
                LEFT JOIN dbo.EmployeeInformation AS E ON E.SystemID=P.ResponsiblePersonId
                 where (ISNULL(pod.BaseAmount,0)-ISNULL(IRD.GRNAmount,0))>0 AND ISNULL(po.IsClosed,0)=0
                
                ) x
				group by x.PartyNature,x.PartyGroup,x.PartyCategory,x.PartySubCategory,x.ResponsiblePerson,x.PartyId,x.PartyName )y
				order by y.PartyNature,y.PartyGroup,y.PartyName";
                return _sqlRepository.GetDataCollection(sql);

            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }
        #endregion

        #region  Receipt from Customer
        public IEnumerable<object> GetReceiptFromCustomerList(string fromDate, string toDate)
        {
            try
            {
                var sql = @"select  P.Code CustomerCode,P.UserName Customer ,V.VoucherNo ReceivedVoucherNo,format(IWO.PostingDate,'dd-MMM-yyyy') ReceivedPostingDate
												,C.Code Currency
												,I.Amount InvoiceAmount,S.InvoiceNo
												,IWOD.Amount Received
												,Balance=I.Amount- SUM(IWOD.Amount)   over (partition by I.Id),isnull(SR.SalesReturn,0) CreditNote
												,VI.VoucherNo InvoiceVoucherNo,format(S.InvoiceDate,'dd-MMM-yyyy')InvoiceDate,VI.DocRefNo InvoiceDocRefNo
												,PaymentSource=case when IWO.PaymentSource<>'' then IWO.PaymentSource when awd.AccountTitle<>'' then 'Advance' else NULL end
												,[BankDetail]=case when bm.AccountTitle<>'' then bm.AccountTitle else awd.AccountTitle end
												,[CashDetail]=Cm.UserName
						                      
						                        from TRN.InvoiceWriteOffDetail IWOD
						                        left join TRN.InvoiceWriteOff IWO on IWO.Id=IWOD.InvoiceWriteOffId
						                        left join TRN.Voucher V on V.Id=IWO.VoucherId
												left join trn.AdvanceWriteOff awo on awo.VoucherId=v.Id
												left join (SELECT awd.AdvanceId,awd.AdvanceWriteOffId,bmawo.AccountTitle FROM TRN.AdvanceWriteOffDetail awd 
														join trn.Advance a on a.Id=awd.AdvanceId
														left join mst.BankMaster bmawo ON bmawo.Id=a.BankMasterId) awd on awd.AdvanceWriteOffId=awo.Id
						                        left JOIN TRN.InvoiceDetail IND on IND.Id=IWOD.InvoiceDetailId 
						                        left join TRN.Invoice I on I.Id=IWOD.InvoiceId
						                        left join TRN.Voucher VI on VI.Id=I.VoucherId
						                        left join SCS.Currency C on C.Id=I.CurrencyId
												left join mst.BankMaster bm ON bm.Id=IWO.BankMasterId
												left join mst.CashMaster cm ON cm.Id=IWO.CashMasterId
												left join (select sum(iwd.Amount) SalesReturn,iwd.InvoiceId from TRN.InvoiceWriteOffDetail iwd 
															join trn.InvoiceWriteOff iw on iw.Id=iwd.InvoiceWriteOffId 
															where iw.sourceType in ('CreditNoteSetOff') and iw.PartyType = 'Customer' group by iwd.InvoiceId)SR ON SR.InvoiceId=I.Id
						                         LEFT JOIN TRN.Sales S on S.VoucherId=I.VoucherId
												 LEFT JOIN (SELECT SalesId,SUM(TransactionAmount) TaxableAmount from TRN.SalesMaterial SM GROUP BY SalesId) SM ON SM.SalesId=S.Id
						                        LEFT JOIN HKP.Party P on I.PartyId=P.Id
                                                where  IWO.PartyType = 'Customer' 
												and I.WrittenOffAmount>0  and  IWO.SourceType in ('CustomerReceipt','CustomerAdvanceWriteOff','CustomerBanksReceipt')
												and IWO.PostingDate  Between '" + fromDate + "' AND '" + toDate + @"'
												 group by IWO.SourceType,P.Code ,P.UserName ,V.VoucherNo , IWO.PostingDate  ,C.Code,I.Amount ,IWOD.Amount,I.Id ,I.Amount ,VI.VoucherNo
												 , S.InvoiceDate ,VI.DocRefNo,S.InvoiceNo,bm.AccountTitle,Cm.UserName,IWO.PaymentSource,awd.AccountTitle,SR.SalesReturn
												 order by IWO.PostingDate ,i.Id desc,V.VoucherNo desc";

                return _sqlRepository.GetDataCollection(sql);
            }
            catch (Exception ex)
            {
                throw new CustomException(ex.Message, ex,
                    Logger.ThrowError(GetType().Name, MethodBase.GetCurrentMethod().Name, null,
                    ErrorType.ServiceError, null, ex.Message, ex.GetType().Name, false, ModuleEnum.Accounts.ToString()));
            }
        }
        public string ReceiptFromCustomerxlsx(List<Dictionary<string, object>> data, string ReportHeader, string reportFileName)
        {
            ExcelEngine excelEngine = null;
            IApplication application = null;
            IWorkbook workbook = null;
            IWorksheet sheet = null;
            var filePath = "";
            try
            {
                excelEngine = new ExcelEngine();
                application = excelEngine.Excel;
                workbook = application.Workbooks.Create(1);
                workbook.Worksheets[0].Name = "ReceiptFromCustomerReport";
                sheet = workbook.Worksheets[0];
                int ROW = 5; int COL = 1;

                #region columns
                sheet[ROW, COL].Text = "Customer Code";
                sheet[ROW, COL].ColumnWidth = 11;
                int ColCustomerCode = COL;
                COL++;

                sheet[ROW, COL].Text = "Customer";
                sheet[ROW, COL].ColumnWidth = 25;
                int ColCustomer = COL;
                COL++;

                sheet[ROW, COL].Text = "Received Voucher No";
                sheet[ROW, COL].ColumnWidth = 15;
                int ColReceivedVoucherNo = COL;
                COL++;

                sheet[ROW, COL].Text = "Received Posting Date";
                sheet[ROW, COL].ColumnWidth = 12;
                int ColReceivedPostingDate = COL;
                COL++;

                sheet[ROW, COL].Text = "Currency";
                sheet[ROW, COL].ColumnWidth = 8;
                int ColCurrency = COL;
                COL++;

                sheet[ROW, COL].Text = "Invoice Amount";
                sheet[ROW, COL].ColumnWidth = 12;
                int ColInvoiceAmount = COL;
                COL++;

                sheet[ROW, COL].Text = "Invoice No";
                sheet[ROW, COL].ColumnWidth = 15;
                int ColInvoiceNo = COL;
                COL++;

                sheet[ROW, COL].Text = "Received Amount";
                sheet[ROW, COL].ColumnWidth = 10;
                int ColReceived = COL;
                COL++;

                sheet[ROW, COL].Text = "Balance";
                sheet[ROW, COL].ColumnWidth = 10;
                int ColBalance = COL;
                COL++;

                sheet[ROW, COL].Text = "Credit Note";
                sheet[ROW, COL].ColumnWidth = 10;
                int ColCreditNote = COL;
                COL++;

                sheet[ROW, COL].Text = "Invoice Voucher No";
                sheet[ROW, COL].ColumnWidth = 15;
                int ColInvoiceVoucherNo = COL;
                COL++;

                sheet[ROW, COL].Text = "Invoice Date";
                sheet[ROW, COL].ColumnWidth = 10;
                int ColInvoiceDate = COL;
                COL++;

                sheet[ROW, COL].Text = "Invoice Doc RefNo";
                sheet[ROW, COL].ColumnWidth = 15;
                int ColInvoiceDocRefNo = COL;
                COL++;

                sheet[ROW, COL].Text = "Payment Source";
                sheet[ROW, COL].ColumnWidth = 12;
                int ColPaymentSource = COL;
                COL++;

                sheet[ROW, COL].Text = "Bank Detail";
                sheet[ROW, COL].ColumnWidth = 15;
                int ColBankDetail = COL;
                COL++;

                sheet[ROW, COL].Text = "Cash Detail";
                sheet[ROW, COL].ColumnWidth = 15;
                int ColCashDetail = COL;

                #endregion columns
                int endCol = COL;
                sheet.Range[ROW, 1, ROW, endCol].CellStyle.Interior.ColorIndex = ExcelKnownColors.Black;
                sheet.Range[ROW, 1, ROW, endCol].CellStyle.Font.Color = ExcelKnownColors.White;
                sheet.Range[ROW, 1, ROW, endCol].CellStyle.Font.Bold = true;
                sheet.Range[ROW, 1, ROW, endCol].CellStyle.Font.Size = 9f;
                sheet.Range[ROW, 1, ROW, endCol].BorderInside(ExcelLineStyle.Hair);
                sheet.Range[ROW, 1, ROW, endCol].BorderAround(ExcelLineStyle.Hair);
                ROW++;

                int startRow = ROW;
                for (int i = 0; i < data.Count; i++)
                {
                    sheet[ROW, ColCustomerCode].Text = data[i]["CustomerCode"].ToString();
                    sheet[ROW, ColCustomer].Text = data[i]["Customer"].ToString();
                    sheet[ROW, ColReceivedVoucherNo].Text = data[i]["ReceivedVoucherNo"].ToString();
                    sheet[ROW, ColReceivedPostingDate].Text = data[i]["ReceivedPostingDate"].ToString();
                    sheet[ROW, ColCurrency].Text = data[i]["Currency"].ToString();
                    sheet[ROW, ColInvoiceAmount].Number = clsStaticInfo.dbl(data[i]["InvoiceAmount"].ToString());
                    sheet[ROW, ColInvoiceAmount].NumberFormat = OTSBD.clsStaticInfo.NumberFormat(2);
                    if (data[i]["InvoiceNo"] != null)
                    {
                        sheet[ROW, ColInvoiceNo].Text = data[i]["InvoiceNo"].ToString();
                    }
                    else
                    {
                        sheet[ROW, ColInvoiceNo].Text = null;
                    }
                    sheet[ROW, ColReceived].Number = clsStaticInfo.dbl(data[i]["Received"].ToString());
                    sheet[ROW, ColReceived].NumberFormat = OTSBD.clsStaticInfo.NumberFormat(2);
                    sheet[ROW, ColBalance].Number = clsStaticInfo.dbl(data[i]["Balance"].ToString());
                    sheet[ROW, ColBalance].NumberFormat = OTSBD.clsStaticInfo.NumberFormat(2);
