										left join TRN.POGGRNMap pg on pg.PoId= po.Id
			                            WHERE PG.GRNId=IR.Id for xml path(''),TYPE).value('.', 'VARCHAR(MAX)'), 1, 1, '')


				    ,PINo= STUFF((select distinct ','+PLC.PINo
